window.CLM_MAP = {"cats":[{"id":"emb","label":"Vocabulary embeddings"},{"id":"latent","label":"Contextual & latent spaces"},{"id":"simplex","label":"Simplex & sphere"},{"id":"onehot","label":"One-hot, binary & flow maps"},{"id":"fewstep","label":"Few-step & one-step"},{"id":"hybrid","label":"Hybrid & scheduled"},{"id":"guide","label":"Guidance & inference"},{"id":"apps","label":"Reasoning, multimodal & evaluation"}],"papers":[{"id":"li2022diffusion","short":"Diffusion-LM","cat":"emb","title":"Diffusion-lm improves controllable text generation","authors":["Xiang Li","John Thickstun","Ishaan Gulrajani","Percy S Liang","Tatsunori B Hashimoto"],"venue":"NeurIPS","year":2022,"url":"https://arxiv.org/abs/2205.14217","arxiv":"2205.14217","code":"https://github.com/XiangLi1999/Diffusion-LM","overview":"Diffusion-LM denoises Gaussian vectors into word vectors. Its continuous intermediate states let simple classifiers control complex attributes such as syntactic structure, without retraining the model.","n":7,"x":350.9,"y":220.0,"r":7.81,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Diffusion-LM uses a reconstruction loss to keep token embeddings decodable and a weighted L2 penalty to discourage excessive embedding norms."},{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"Early models, such as Diffusion-LM, use squared-error losses to predict the clean representation over learned vocabulary embeddings, with added regularization to prevent collapse (Section 3.1.2)."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"Diffusion-LM trains classifiers on noisy representations and uses their gradients to refine each denoising update."},{"part":"1 Introduction","secTitle":"","text":"By contrast, continuous models represent text with vectors and learn to transform noise into these representations before decoding them into tokens."}],"related":["dieleman2022continuous","han2023ssd","gulrajani2023likelihood"]},{"id":"gong2022diffuseq","short":"DiffuSeq","cat":"emb","title":"Diffuseq: Sequence to sequence text generation with diffusion models","authors":["Shansan Gong","Mukai Li","Jiangtao Feng","Zhiyong Wu","LingPeng Kong"],"venue":"ICLR","year":2023,"url":"https://arxiv.org/abs/2210.08933","arxiv":"2210.08933","code":"https://github.com/Shark-NLP/DiffuSeq","overview":"DiffuSeq applies diffusion to sequence-to-sequence text generation. It performs comparably to or better than six established baselines and produces highly diverse outputs.","n":3,"x":533.5,"y":178.8,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Related objectives are used by DiffuSeq, SeqDiffuSeq, and GENIE."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"DiffuSeq processes the source and noisy target jointly, whereas SeqDiffuSeq encodes the source once and reuses its outputs throughout denoising."},{"part":"7 Applications and Evaluation","secTitle":"7.2 Conditional Language Modeling","text":"DiffuSeq conditions on the source through partial noising and evaluates on paraphrasing, question generation, and dialogue, while SeqDiffuSeq and GENIE encode the source with a separate encoder and extend the evaluation to machine translation and summarization, respectively."}],"related":["yuan2022seqdiffuseq","lin2023text"]},{"id":"yuan2022seqdiffuseq","short":"SeqDiffuSeq","cat":"emb","title":"Seqdiffuseq: Text diffusion with encoder-decoder transformers","authors":["Hongyi Yuan","Zheng Yuan","Chuanqi Tan","Fei Huang","Songfang Huang"],"venue":"arXiv","year":2022,"url":"https://arxiv.org/abs/2212.10325","arxiv":"2212.10325","code":"https://github.com/Yuanhy1997/SeqDiffuSeq","overview":"SeqDiffuSeq adapts continuous diffusion to sequence-to-sequence text generation with an encoder-decoder Transformer that models the denoising function.","n":6,"x":494.3,"y":186.8,"r":7.56,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Related objectives are used by DiffuSeq, SeqDiffuSeq, and GENIE."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"SeqDiffuSeq adjusts a separate noise schedule for each token position so that its denoising loss changes approximately linearly with time."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"SED, SeqDiffuSeq, and ELF use denoised token embeddings."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"DiffuSeq processes the source and noisy target jointly, whereas SeqDiffuSeq encodes the source once and reuses its outputs throughout denoising."}],"related":["gong2022diffuseq","strudel2022self","lin2023text","hu2026elf","guo2026continuous","chavan2026large"]},{"id":"lin2023text","short":"GENIE","cat":"emb","title":"Text generation with diffusion language models: A pre-training approach with continuous paragraph denoise","authors":["Zhenghao Lin","Yeyun Gong","Yelong Shen","Tong Wu","Zhihao Fan","Chen Lin","Nan Duan","Weizhu Chen"],"venue":"ICML","year":2023,"url":"https://arxiv.org/abs/2212.11685","arxiv":"2212.11685","code":"https://github.com/microsoft/ProphetNet","overview":"GENIE is a large pretrained diffusion language model with an encoder and a diffusion decoder. It trains on a continuous paragraph denoising objective that reconstructs clean paragraphs from corrupted ones.","n":2,"x":511.5,"y":167.5,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Related objectives are used by DiffuSeq, SeqDiffuSeq, and GENIE."},{"part":"7 Applications and Evaluation","secTitle":"7.2 Conditional Language Modeling","text":"DiffuSeq conditions on the source through partial noising and evaluates on paraphrasing, question generation, and dialogue, while SeqDiffuSeq and GENIE encode the source with a separate encoder and extend the evaluation to machine translation and summarization, respectively."}],"related":["yuan2022seqdiffuseq","gong2022diffuseq"]},{"id":"dieleman2022continuous","short":"CDCD","cat":"emb","title":"Continuous diffusion for categorical data","authors":["Sander Dieleman","Laurent Sartran","Arman Roshannai","Nikolay Savinov","Yaroslav Ganin","Pierre H Richemond","Arnaud Doucet","Robin Strudel","Chris Dyer","Conor Durkan","et al."],"venue":"arXiv","year":2022,"url":"https://arxiv.org/abs/2211.15089","arxiv":"2211.15089","code":null,"overview":"CDCD models categorical data with diffusion that is continuous in both time and input space, and the authors demonstrate it on several language modeling tasks.","n":12,"x":344.8,"y":188.9,"r":8.83,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"CDCD replaces embedding regression with cross-entropy and normalizes the embeddings to prevent unbounded norm growth."},{"part":"3 Continuous Language Models","secTitle":"3.2.2 Cross-Entropy Objectives","text":"Given an embedding table $E$, the predicted token probabilities yield an estimate of the expected data embedding through … CDCD uses this expected embedding to obtain the score through the Gaussian conversion described above, an approach it calls score interpolation."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"CDCD uses cross-entropy as a proxy for remaining token uncertainty and learns a time warp that makes this quantity approximately linear."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"Bidirectional transformers are the most common architectural choice, as in CDCD and RDLM."}],"related":["li2022diffusion","yang2026large","strudel2022self","meshchaninov2026train","jo2026continuous","guo2026continuous","gulrajani2023likelihood","chen2026langflow"]},{"id":"gulrajani2023likelihood","short":"Plaid","cat":"emb","title":"Likelihood-Based Diffusion Language Models","authors":["Ishaan Gulrajani","Tatsunori B Hashimoto"],"venue":"NeurIPS","year":2023,"url":"https://arxiv.org/abs/2305.18619","arxiv":"2305.18619","code":"https://github.com/igul222/plaid","overview":"Plaid takes the first steps toward closing the likelihood gap with autoregressive models. The authors combine better maximum-likelihood training, scaling laws, and more compute.","n":9,"x":378.9,"y":114.7,"r":8.25,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Plaid and RePlaid instead learn normalized embeddings through a complete likelihood objective, balancing reconstruction and diffusion terms rather than optimizing denoising error alone (Section 3.2)."},{"part":"3 Continuous Language Models","secTitle":"3.2.4 Likelihood Objectives","text":"Plaid adopts variational diffusion to optimize a tractable likelihood bound."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"Plaid and RePlaid learn how often to sample each noise level to reduce the variance of the training loss estimate."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Plaid and Fixed-Point Flows interpret self-conditioning through fixed-point refinement."}],"related":["yang2026continuous","yoo2026self","li2022diffusion","dieleman2022continuous","davis2026scaling","chen2026langflow"]},{"id":"yang2026continuous","short":"RePlaid","cat":"emb","title":"Continuous diffusion scales competitively with discrete diffusion for language","authors":["Zhihan Yang","Wei Guo","Shuibai Zhang","Subham Sekhar Sahoo","Yongxin Chen","Arash Vahdat","Morteza Mardani","John Thickstun"],"venue":"NeurIPS","year":2026,"url":"https://arxiv.org/abs/2605.18530","arxiv":"2605.18530","code":null,"overview":"RePlaid revisits Plaid and aligns its architecture with modern discrete diffusion models. The authors use it to establish a scaling law for continuous diffusion that rivals discrete diffusion.","n":8,"x":351.9,"y":104.8,"r":8.04,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.7 What Makes a Good Representation?","text":"In RePlaid, Yang et al. find that adding an auxiliary cross-entropy loss disperses low-rank embeddings and worsens its likelihood bound, illustrating that low effective dimension is not necessarily a failure."},{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Plaid and RePlaid instead learn normalized embeddings through a complete likelihood objective, balancing reconstruction and diffusion terms rather than optimizing denoising error alone (Section 3.2)."},{"part":"3 Continuous Language Models","secTitle":"3.2.4 Likelihood Objectives","text":"RePlaid revisits this approach with modern transformer backbones and shows competitive likelihoods at scale."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"Plaid and RePlaid learn how often to sample each noise level to reduce the variance of the training loss estimate."}],"related":["gulrajani2023likelihood","guo2026continuous","draxler2026parallel2","davis2026scaling"]},{"id":"gao2022empowering","short":"Difformer","cat":"emb","title":"Empowering Diffusion Models on the Embedding Space for Text Generation","authors":["Zhujin Gao","Junliang Guo","Xu Tan","Yongxin Zhu","Fang Zhang","Jiang Bian","Linli Xu"],"venue":"NAACL","year":2024,"url":"https://arxiv.org/abs/2212.09412","arxiv":"2212.09412","code":"https://github.com/zhjgao/difformer","overview":"Difformer studies the optimization problems of diffusing on embeddings. It adds an anchor loss to prevent embedding collapse and a noise schedule better suited to training the denoiser.","n":3,"x":368.7,"y":263.1,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Difformer finds that reconstructing clean embeddings can become too easy to provide sufficient regularization."},{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"Difformer and DINOISER instead predict target lengths and generate candidates across several lengths and noise initializations."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.1 Reducing Solver Error","text":"Difformer showed that an embedding diffusion model that predicts clean embeddings, combined with a cross-entropy “anchor” loss and a rescaled noise schedule, retains its quality when generation is reduced to a few dozen steps."}],"related":["inference_ye2024dinoiser"]},{"id":"chen2026langflow","short":"LangFlow","cat":"emb","title":"LangFlow: Continuous Diffusion Rivals Discrete in Language Modeling","authors":["Yuxin Chen","Chumeng Liang","Hangke Sui","Ruihan Guo","Chaoran Cheng","Jiaxuan You","Ge Liu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2604.11748","arxiv":"2604.11748","code":"https://github.com/nealchen2003/LangFlow","overview":"LangFlow connects embedding-space diffusion to flow matching through Bregman divergence. It adds an ODE-based likelihood bound and an information-uniform noise schedule, and it rivals discrete diffusion.","n":10,"x":362.3,"y":164.9,"r":8.45,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"LangFlow likewise combines cross-entropy with normalized embeddings."},{"part":"3 Continuous Language Models","secTitle":"3.2.2 Cross-Entropy Objectives","text":"LangFlow takes the same approach and uses cross-entropy for flow matching with vocabulary embeddings."},{"part":"3 Continuous Language Models","secTitle":"3.2.4 Likelihood Objectives","text":"LangFlow trains with denoising cross-entropy but derives an ODE-based bound for likelihood evaluation."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"LangFlow follows a similar principle, fitting the uncertainty curve over the log noise-to-signal ratio."}],"related":["lee2026flow","hu2026elf","gulrajani2023likelihood","dieleman2022continuous","davis2026scaling"]},{"id":"yang2026large","short":"Sigma","cat":"emb","title":"Large Language Continuous Diffusion Models","authors":["Zhihan Yang","Wei Guo","Jean-Marie Lemercier","Simon Welker","Yonggan Fu","Mohammad Mahdi Kamani","Sajad Norouzi","Julius Berner","Tomas Geffner","Karsten Kreis","Yongxin Chen","Molei Tao","John Thickstun","Pavlo Molchanov","Ante Jukić","Arash Vahdat","Morteza Mardani"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.02665","arxiv":"2610.02665","code":null,"overview":"Sigma is a large continuous diffusion language model at 3B and 8B parameters. It trains blockwise by likelihood, starts from pretrained autoregressive weights, and relies on guidance and score temperature for reasoning and coding.","n":11,"x":357.3,"y":133.9,"r":8.65,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Sigma finds that learned unit-norm vocabulary vectors concentrate in a few effective dimensions."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"Recent large models, including Sigma and Lafa, adopt this attention pattern for prefix caching."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"CDCD applies temperature and top-$p$ truncation to its categorical predictions at each denoising step, while Sigma rescales the continuous score."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"Outside the two-time denoiser parameterization, ELF uses progressive distillation to repeatedly cut the number of steps of an embedded flow in half down to one step, Sigma uses parallel decoding distillation to compress large blockwise embedding diffusion into a few steps, and Warczyński et al. use shortcut modeling to learn embedded velocity from data and self-distill it into the average velocity."}],"related":["chavan2026large","kim2026gumbel","han2024david","dieleman2022continuous","davis2026scaling"]},{"id":"chavan2026large","short":"Lafa","cat":"emb","title":"Large Flow Language Models","authors":["Arnav Chavan","Chanhyuk Lee","Udbhav Bamba","Jaehoon Yoo","Seunghoon Hong","Aditi Raghunathan","Jinwoo Kim"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.28559","arxiv":"2610.28559","code":"https://github.com/lafa-gh/large-flow-lms","overview":"Lafa scales flow language models to 8B parameters. It flows asynchronously within blocks and uses causal attention on the prefix, so it can adapt pretrained autoregressive models and decode quickly with prefix caching.","n":17,"x":390.7,"y":150.4,"r":9.65,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Lafa takes an intermediate approach by adapting a pretrained AR model's embedding table while preserving each vector's original norm."},{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"Lafa combines cross-entropy on token probabilities with squared error on the corresponding mean embeddings."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"Lafa learns a separate time reparameterization for each token position, using denoising cross-entropy to allocate more training samples to noise levels with higher losses."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"Recent large models, including Sigma and Lafa, adopt this attention pattern for prefix caching."}],"related":["yang2026large","yuan2022seqdiffuseq","strudel2022self","shen2026flashmap","schiff2026clock","kim2026gumbel","han2024david","guo2026continuous"]},{"id":"li2026convergeflow","short":"ConvergeFlow","cat":"emb","title":"Convergeflow: Language flow with provable convergence to token embeddings","authors":["Na Li","Yuchen Jiao","Changxiao Cai","Gen Li"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2608.23551","arxiv":"2608.23551","code":"https://github.com/Na-Li66/ConvergeFlow","overview":"ConvergeFlow constrains the data predictor to the convex hull of token embeddings and trains only with mean squared error. The authors prove convergence to valid token embeddings, so no cross-entropy decoder is needed.","n":1,"x":341.7,"y":244.8,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"ConvergeFlow predicts a weighted average of vocabulary embeddings like CDCD and LangFlow, but trains this continuous prediction with squared error."}],"related":[]},{"id":"kouzelis2026self","short":"SERF","cat":"emb","title":"Self-Regularized Flow Language Models","authors":["Theodoros Kouzelis","Spyros Gidaris","Nikos Komodakis"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.37115","arxiv":"2610.37115","code":null,"overview":"SERF improves continuous diffusion language models through noisy-to-clean self-distillation, using the denoising trajectory itself as a learning signal.","n":1,"x":362.3,"y":239.0,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.2.2 Cross-Entropy Objectives","text":"SERF further adds a self-distillation loss whose teacher is an exponential moving average of the model given a less noisy input, to speed up training."}],"related":[]},{"id":"liu2024text","short":"TREC","cat":"emb","title":"Text Diffusion with Reinforced Conditioning","authors":["Yuxuan Liu","Tianchi Yang","Shaohan Huang","Zihan Zhang","Haizhen Huang","Furu Wei","Weiwei Deng","Feng Sun","Qi Zhang"],"venue":"arXiv","year":2024,"url":"https://arxiv.org/abs/2402.14843","arxiv":"2402.14843","code":null,"overview":"TREC analyzes text diffusion models and addresses two limitations: self-conditioning that degrades during training, and misalignment between training and sampling.","n":1,"x":373.7,"y":222.3,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"TREC and FastDiSS instead modify training, the former keeping self-conditioning beneficial through reinforcement learning and the latter perturbing the self-conditioning input to match the errors of few-step sampling."}],"related":[]},{"id":"luo2026designing","short":"LangDiT","cat":"emb","title":"Designing Transformers for Continuous Diffusion Language Models","authors":["Weijian Luo","Yujian Chen","Hao Jiang","Guang Cheng","Tianyang Hu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.22330","arxiv":"2610.22330","code":null,"overview":"LangDiT comes from a systematic study of Transformer architectures for continuous diffusion language models, covering choices such as normalization and noise conditioning.","n":1,"x":384.9,"y":200.5,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"LangDiT revisits normalization, noise conditioning, and self-conditioning together, and improves generation across model formulations."}],"related":[]},{"id":"shabalin2025smoothie","short":"Smoothie","cat":"emb","title":"Smoothie: Smoothing Diffusion on Token Embeddings for Text Generation","authors":["Alexander Shabalin","Viacheslav Meshchaninov","Dmitry Vetrov"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2505.18853","arxiv":"2505.18853","code":"https://github.com/ashaba1in/smoothie","overview":"Smoothie progressively smooths token embeddings based on semantic similarity. This removes information gradually while keeping a natural way to decode tokens.","n":1,"x":384.0,"y":242.8,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"Smoothie likewise freezes BERT embeddings, but it adds noise to the distances between each position and all token embeddings, so that corruption first blurs semantically similar tokens."}],"related":[]},{"id":"su2026rectified","short":"ReLF","cat":"emb","title":"Rectified Language Flow","authors":["Baiyu Su","Runlong Liao","Lizhang Chen","Qiang Liu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.33811","arxiv":"2610.33811","code":null,"overview":"ReLF transports noise to token embeddings with rectified flow. It combines fixed Hellinger-SVD embeddings, self-conditioning guidance, and regularized reflow.","n":1,"x":391.9,"y":262.3,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"ReLF similarly retrains on its own rollouts over several rounds, pulling the weights back toward the base model after each round to limit drift."}],"related":[]},{"id":"raya2026noise","short":"InfoNoise","cat":"emb","title":"Noise Scheduling as Information-Guided Allocation in Diffusion Training","authors":["Gabriel Raya","Bac Nguyen","Georgios Batzolis","Yuhta Takida","Dejan Stancevic","Naoki Murata","Chieh-Hsin Lai","Yuki Mitsufuji","Luca Ambrogioni"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2602.18647","arxiv":"2602.18647","code":null,"overview":"InfoNoise adapts the noise schedule during training. It estimates a conditional-entropy-rate profile from denoising losses and reallocates effort to the most informative noise levels.","n":1,"x":396.9,"y":224.7,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"CoBit applies the same principle to bitstreams through the information-guided allocation of InfoNoise, which estimates how fast this uncertainty changes from denoising errors."}],"related":[]},{"id":"strudel2022self","short":"SED","cat":"latent","title":"Self-conditioned embedding diffusion for text generation","authors":["Robin Strudel","Corentin Tallec","Florent Altché","Yilun Du","Yaroslav Ganin","Arthur Mensch","Will Grathwohl","Nikolay Savinov","Sander Dieleman","Laurent Sifre","et al."],"venue":"arXiv","year":2022,"url":"https://arxiv.org/abs/2211.04236","arxiv":"2211.04236","code":null,"overview":"SED runs continuous diffusion on token embeddings for conditional and unconditional text generation. Its samples are comparable to those of standard autoregressive models.","n":5,"x":117.2,"y":364.0,"r":7.3,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.2 Vocabulary Embeddings","text":"SED uses normalized vocabulary embeddings from a separately pretrained BERT model and freezes them after finding joint learning unstable."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"SED, SeqDiffuSeq, and ELF use denoised token embeddings."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"SED adds a time embedding to the projected input, whereas CDCD uses time-dependent shifts and scales of normalized features within each layer."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"SED removes both text context and self-conditioning, while Lafa removes the conditioning prefix in block autoregression."}],"related":["yuan2022seqdiffuseq","hu2026elf","dieleman2022continuous","chavan2026large"]},{"id":"shabalin2025tencdm","short":"TEncDM","cat":"latent","title":"Tencdm: Understanding the properties of the diffusion model in the space of language model encodings","authors":["Alexander Shabalin","Viacheslav Meshchaninov","Egor Chimbulatov","Vladislav Lapikov","Roman Kim","Grigory Bartosh","Dmitry Molchanov","Sergey Markov","Dmitry Vetrov"],"venue":"AAAI","year":2025,"url":"https://arxiv.org/abs/2402.19097","arxiv":"2402.19097","code":"https://github.com/M0RJIQUE/tencdm","overview":"TEncDM diffuses in the space of pretrained language model encodings, which carry context that plain embeddings lack. The authors examine how the encoder, decoder, noise schedule, and self-conditioning affect generation.","n":4,"x":60.3,"y":313.1,"r":7.0,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"TEncDM generates frozen encoder outputs from models such as BERT and T5, while Embedded Language Flows (ELF) use T5 representations as the targets of flow matching."},{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"TEncDM pairs squared-error prediction of frozen encoder states with a separate bidirectional decoder trained by cross-entropy on perturbed states."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Comparisons with vocabulary embeddings support the benefits of contextualization for continuous generation."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Repeated feedback can also increase confidence and reinforce repetitive text, motivating the inference adjustments discussed in Section 4.3."}],"related":["zhang2026low","meshchaninov2026train","hu2026elf"]},{"id":"shen2026codar","short":"CoDAR","cat":"latent","title":"Codar: Continuous diffusion language models are more powerful than you think","authors":["Junzhe Shen","Jieru Zhao","Ziwei He","Zhouhan Lin"],"venue":"EMNLP","year":2026,"url":"https://arxiv.org/abs/2603.02547","arxiv":"2603.02547","code":null,"overview":"CoDAR identifies token rounding as a main bottleneck of continuous diffusion. It keeps diffusion fully continuous and adds an autoregressive decoder that performs contextual rounding to tokens.","n":1,"x":20.0,"y":229.5,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Lovelace et al. use BART's pretrained AR decoder, while CoDAR trains a separate AR decoder on perturbed outputs of a frozen Qwen3-Embedding encoder."}],"related":[]},{"id":"hu2026elf","short":"ELF","cat":"latent","title":"Elf: Embedded language flows","authors":["Keya Hu","Linlu Qiu","Yiyang Lu","Hanhong Zhao","Tianhong Li","Yoon Kim","Jacob Andreas","Kaiming He"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.10938","arxiv":"2605.10938","code":"https://github.com/lillian039/ELF","overview":"ELF applies continuous-time flow matching in embedding space with minimal adaptation to discrete data. It stays continuous until the final step, where it maps the state to tokens.","n":18,"x":100.8,"y":343.0,"r":9.8,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.2.1 Prediction Parameterizations","text":"In ELF, Hu et al. likewise find clean-embedding prediction more reliable than noise or velocity prediction across contextual representations."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"TEncDM generates frozen encoder outputs from models such as BERT and T5, while Embedded Language Flows (ELF) use T5 representations as the targets of flow matching."},{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"ELF shares a network between denoising and decoding."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"SED, SeqDiffuSeq, and ELF use denoised token embeddings."}],"related":["lee2026flow","chen2026langflow","zhang2026scaling","yuan2022seqdiffuseq","yoo2026self","strudel2022self","shabalin2025tencdm","meshchaninov2026train"]},{"id":"li2026elf","short":"ELF-REG","cat":"latent","title":"ELF-REG: Scaling Continuous Diffusion Language Models to Reasoning Tasks","authors":["Zeyu Michael Li","William Xingxu Chen","Bingshuo Qian","Jiayin Liu","Xiang Cheng"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.29102","arxiv":"2609.29102","code":"https://github.com/lizeyu090312/scaling_dLM","overview":"ELF-REG scales ELF to math reasoning and code generation. A frozen autoregressive teacher supervises intermediate denoiser features and supplies a global representation that is denoised jointly with the response.","n":3,"x":118.4,"y":322.0,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"FMLM$^\\star$ and ELF-REG use causal hidden states from GPT-2 and Qwen, respectively, while MF-1 applies T5 independently within short token blocks."},{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"ELF-REG instead executes a fixed number of initial updates on a finer time grid, then decodes its latest prediction of the clean representations."},{"part":"7 Applications and Evaluation","secTitle":"7.2.2 Tasks and Evaluation for Large Models","text":"ELF-REG extends ELF to math and code."}],"related":["yoo2026self"]},{"id":"guo2026deltaflow","short":"DeltaFlow","cat":"latent","title":"DeltaFlow: Noise-Adaptive Bidirectional Gated Delta Networks for Embedded Language Flows","authors":["Guangfu Guo","Xiaoqian Lu","Linsey Pang","Weiran Yao","Haolin Chen","Kunpeng Liu","Long Cheng"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2608.01240","arxiv":"2608.01240","code":null,"overview":"DeltaFlow replaces quadratic attention in ELF with a noise-adaptive bidirectional gated delta network, which makes each denoising step cheaper.","n":2,"x":143.9,"y":324.4,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"DeltaFlow adopts the same representation with a different denoising architecture."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"DeltaFlow instead reduces the cost of mixing information across positions."}],"related":[]},{"id":"zhang2026scaling","short":"Diffusibility","cat":"latent","title":"Scaling and Distilling Text Embeddings for Better Diffusibility","authors":["Zekai Zhang","Yunjie Tian","Yanjin He","Xiaoyan Zhang","Dongdi Zhao","Qing Qu","Di Fu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.01016","arxiv":"2610.01016","code":"https://github.com/la0ka1/diffusing-scaled-text-embeddings","overview":"The authors ask which text embedding makes the best latent space. Stronger embedding models help, but raw embeddings can be too discriminative, so the authors also distill them to improve diffusibility.","n":3,"x":130.2,"y":389.1,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Zhang et al. find that T5Gemma-2 encodings overly separate even plausible alternative words, which they attribute to training against one-hot token labels."},{"part":"3 Continuous Language Models","secTitle":"3.1.7 What Makes a Good Representation?","text":"Zhang et al. find that improvements in pretrained encoders can benefit diffusion, but strong discriminative performance alone does not ensure a suitable generation space."},{"part":"8 Challenges and Future Directions","secTitle":"8.1 Scalable Language Representations","text":"Pretrained encoders provide linguistic structure, although their representations may require adaptation."}],"related":["meshchaninov2026cosmos","hu2026elf"]},{"id":"lovelace2023latent","short":"LD4LG","cat":"latent","title":"Latent diffusion for language generation","authors":["Justin Lovelace","Varsha Kishore","Chao Wan","Eliot Shekhtman","Kilian Q Weinberger"],"venue":"NeurIPS","year":2023,"url":"https://arxiv.org/abs/2212.09462","arxiv":"2212.09462","code":"https://github.com/justinlovelace/latent-diffusion-for-language","overview":"LD4LG learns a high-quality autoencoder from an encoder-decoder language model, then trains continuous diffusion in its latent space. A pretrained decoder turns sampled latents into text.","n":4,"x":20.0,"y":265.7,"r":7.0,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"LD4LG uses a fixed number of learned queries to cross-attend to frozen BART or T5 encoder outputs."},{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"ELF uses one final evaluation of the denoising network to predict all tokens in parallel, whereas LD4LG generates tokens autoregressively from its latents."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Early work by Lovelace et al. applied diffusion to frozen BART encoder outputs, compressed into a fixed number of latent vectors."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Lovelace et al. use BART's pretrained AR decoder, while CoDAR trains a separate AR decoder on perturbed outputs of a frozen Qwen3-Embedding encoder."}],"related":["hu2026elf"]},{"id":"zhang2023planner","short":"PLANNER","cat":"latent","title":"Planner: Generating diversified paragraph via latent language diffusion model","authors":["Yizhe Zhang","Jiatao Gu","Zhuofeng Wu","Shuangfei Zhai","Joshua Susskind","Navdeep Jaitly"],"venue":"NeurIPS","year":2023,"url":"https://arxiv.org/abs/2306.02531","arxiv":"2306.02531","code":"https://github.com/apple-aiml-research/ml-planner","overview":"PLANNER combines latent semantic diffusion with autoregressive generation. The diffusion stage exercises global control over a paragraph, and the autoregressive decoder keeps the text fluent.","n":1,"x":112.2,"y":299.6,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"PLANNER selects a small set of contextual BERT states to represent a paragraph and trains a GPT-2 decoder to reconstruct it."}],"related":[]},{"id":"lovelace2024diffusion","short":"DGLM","cat":"latent","title":"Diffusion guided language modeling","authors":["Justin Lovelace","Varsha Kishore","Yiwei Chen","Kilian Weinberger"],"venue":"Findings of ACL","year":2024,"url":"https://arxiv.org/abs/2408.04220","arxiv":"2408.04220","code":"https://github.com/justinlovelace/Diffusion-Guided-LM","overview":"DGLM uses a guided diffusion model to produce a latent proposal that steers an autoregressive language model. This pairs the easy guidance of diffusion with the low perplexity of autoregressive models.","n":2,"x":135.5,"y":302.2,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"DGLM generates a single continuation embedding in the space of the contrastively trained Sentence-T5 encoder, then conditions an AR model on it."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"DGLM evaluates a classifier on the predicted clean sentence embedding and differentiates through the denoiser, allowing the classifier to be trained on uncorrupted embeddings."}],"related":[]},{"id":"meshchaninov2026cosmos","short":"Cosmos","cat":"latent","title":"Cosmos: Compressed and smooth latent space for text diffusion modeling","authors":["Viacheslav Meshchaninov","Egor Chimbulatov","Alexander Shabalin","Aleksandr Abramov","Dmitry Vetrov"],"venue":"NeurIPS","year":2025,"url":"https://arxiv.org/abs/2506.21170","arxiv":"2506.21170","code":"https://github.com/MeshchaninovViacheslav/cosmos","overview":"Cosmos generates text in a compressed, smooth latent space built for diffusion. Its autoencoder trains on token reconstruction and on alignment with a frozen pretrained language encoder.","n":3,"x":150.1,"y":413.6,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"Cosmos also compresses contextual states with learned queries, but reconstructs tokens in parallel."},{"part":"3 Continuous Language Models","secTitle":"3.2.3 Regression Objectives","text":"Cosmos similarly separates latent regression from token reconstruction after learning a compressed autoencoding space."},{"part":"8 Challenges and Future Directions","secTitle":"8.1 Scalable Language Representations","text":"Pretrained encoders provide linguistic structure, although their representations may require adaptation."}],"related":["zhang2026scaling","hu2026elf"]},{"id":"jiang2026textldm","short":"TextLDM","cat":"latent","title":"TextLDM: Language Modeling with Continuous Latent Diffusion","authors":["Jiaxiu Jiang","Jingjing Ren","Wenbo Li","Bo Wang","Haoze Sun","Yijun Yang","Jianhui Liu","Yanbing Zhang","Shenghe Zheng","Yuan Zhang","et al."],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.07748","arxiv":"2605.07748","code":null,"overview":"TextLDM transfers the visual latent diffusion recipe to text with minimal changes. A Transformer VAE with representation alignment produces latents, and a standard DiT performs flow matching on them.","n":1,"x":273.7,"y":278.2,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Contextual representations can also be pretrained through autoencoding, as in TextLDM and AURORA-LM."}],"related":["liang2026aurora"]},{"id":"meshchaninov2026train","short":"LDLM","cat":"latent","title":"How to train your latent diffusion language model jointly with the latent space","authors":["Viacheslav Meshchaninov","Alexander Shabalin","Egor Chimbulatov","Nikita Gushchin","Ilya Koziev","Alexander Korotin","Dmitry Vetrov"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.07933","arxiv":"2605.07933","code":null,"overview":"LDLM trains its latent encoder, diffusion model, and decoder jointly by reshaping a pretrained language model's representations. The authors show that naive joint training fails and propose a simple recipe.","n":3,"x":103.8,"y":387.4,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"LDLM adapts pretrained representations through joint training, using a trainable encoder to reshape frozen GPT-2 states."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Comparisons with vocabulary embeddings support the benefits of contextualization for continuous generation."},{"part":"8 Challenges and Future Directions","secTitle":"8.1 Scalable Language Representations","text":"Learning representations jointly with the generator allows them to adapt to the generative task, but requires balancing reconstruction and generation objectives to avoid collapse."}],"related":["shabalin2025tencdm","hu2026elf","guo2026continuous","dieleman2022continuous"]},{"id":"guo2026continuous","short":"Cola DLM","cat":"latent","title":"Continuous latent diffusion language model","authors":["Hongcan Guo","Qinyu Zhao","Yian Zhao","Shen Nie","Rui Zhu","Qiushan Guo","Feng Wang","Tao Yang","Hengshuang Zhao","Guoqiang Wei","et al."],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.06548","arxiv":"2605.06548","code":"https://github.com/ByteDance-Seed/Cola-DLM","overview":"Cola DLM is a hierarchical latent diffusion model. A text VAE learns the latent mapping, a block-causal DiT models a global semantic prior, and conditional decoding produces the text.","n":5,"x":165.1,"y":367.1,"r":7.3,"mentions":[{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.1 Training from Scratch","text":"Guo et al. similarly study how the VAE latent space of Cola DLM behaves at scale."},{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Cola DLM first pretrains a causal VAE with additional masking losses, then trains it jointly with the flow model, using a reference encoder to regularize changes to the latent space."},{"part":"4 Inference Strategies","secTitle":"4.6 Inference Efficiency","text":"SeqDiffuSeq encodes its source sequence once, while blockwise models reuse the key-value (KV) cache of completed prefixes."},{"part":"8 Challenges and Future Directions","secTitle":"8.1 Scalable Language Representations","text":"Learning representations jointly with the generator allows them to adapt to the generative task, but requires balancing reconstruction and generation objectives to avoid collapse."}],"related":["yuan2022seqdiffuseq","yang2026continuous","meshchaninov2026train","draxler2026parallel2","dieleman2022continuous","davis2026scaling","chavan2026large"]},{"id":"liang2026aurora","short":"AURORA-LM","cat":"latent","title":"AURORA-LM: Autoencoding Unified Representation for Continuous-Latent Diffusion Language Modeling","authors":["Jiajun Liang","Yucheng Liao","Yukang Cao","Jiazhe Wei","Ken Li","Wende Tan","Jiankun Zhang","ZY Cui","Jingkang Yang","Liucheng Guo","et al."],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2608.02602","arxiv":"2608.02602","code":"https://github.com/fyv587/AURORA-LM","overview":"AURORA-LM keeps a high-capacity, decodable text latent instead of compressing it to ease diffusion, and it designs the diffusion model to learn that latent's distribution directly.","n":1,"x":283.6,"y":256.8,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"Contextual representations can also be pretrained through autoencoding, as in TextLDM and AURORA-LM."}],"related":["jiang2026textldm"]},{"id":"dong2026language","short":"Manta-LM","cat":"latent","title":"Language Generation as Optimal Control: Closed-Loop Diffusion in Latent Control Space","authors":["ZiYi Dong","Yuliang Huang","Weijian Deng","Xiangyang Ji","Liang Lin","Pengxu Wei"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.14531","arxiv":"2605.14531","code":null,"overview":"Manta-LM casts language generation as stochastic optimal control. It uses flow matching in a latent control space to approximate a closed-loop optimal policy.","n":1,"x":127.6,"y":345.8,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"Manta-LM downsamples the sequence with a convolutional VAE, while CALM represents fixed-size token chunks as individual continuous vectors and generates these vectors autoregressively."}],"related":[]},{"id":"du2026continuous","short":"Decoder Interface","cat":"latent","title":"Continuous Language Diffusion as a Decoder-Interface Problem","authors":["Zhicheng Du","Lan Ma"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.08810","arxiv":"2606.08810","code":null,"overview":"The authors study why continuous models generate fluent text from noisy embeddings. They identify a decoder-basin mechanism and propose a diagnostic protocol that exposes failures hidden by scalar metrics.","n":1,"x":139.5,"y":366.6,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.7 What Makes a Good Representation?","text":"Du and Ma find that accurate reconstruction of clean representations and low denoising error can coexist with unreliable decoding of generated states."}],"related":[]},{"id":"feng2026denoising","short":"BLD","cat":"latent","title":"Denoising Blocks, Not Tokens: Efficient Compressed Continuous Diffusion with Branching Token Realization","authors":["Xinsong Feng","Peng Du","Zhizhuo Yang","Daniel M Bikel","Jiayun Wang","Haipeng Chen"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.09311","arxiv":"2610.09311","code":null,"overview":"BLD lets one continuous state represent many tokens. It compresses a 1024-token sequence into 64 block latents, which makes each denoising step much cheaper.","n":1,"x":90.9,"y":439.5,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"BLD compresses contiguous spans into vectors and pairs them with AR decoding branches, allowing several spans to be expanded into text in parallel."}],"related":[]},{"id":"yuan2026one","short":"JPEG-DLM","cat":"latent","title":"One Latent, Many Tokens: Jointly Learning Compressed Embeddings for Efficient Language Diffusion","authors":["Yulin Yuan","Ying Zhang","Xiangming Meng"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.33698","arxiv":"2609.33698","code":"https://github.com/infiniteYuanyl/JPEG-DLM","overview":"JPEG-DLM jointly trains a compressor, a flow matching model, and a decoder, so its compressed embeddings are easier to model with diffusion and to decode.","n":1,"x":66.7,"y":416.2,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"JPEG-DLM jointly trains a compressor over frozen T5 states, a flow model, and a parallel decoder."}],"related":[]},{"id":"ollu2026denoising","short":"H-CoBit","cat":"latent","title":"Denoising Hierarchical Representations: Joint Continuous Diffusion for Language Modeling","authors":["Mathias Ollu","Nikos Komodakis"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.08738","arxiv":"2610.08738","code":"https://github.com/matol-16/HCDLM","overview":"H-CoBit diffuses tokens jointly with coarser clusters of pretrained token embeddings. This adds semantic structure to the representation with little extra compute.","n":2,"x":183.5,"y":390.6,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"H-CoBit adds linguistic structure by augmenting token codes with codes for clusters of pretrained token embeddings and denoising both jointly."},{"part":"8 Challenges and Future Directions","secTitle":"8.1 Scalable Language Representations","text":"Ollu and Komodakis jointly denoise token representations and coarser semantic cluster codes, demonstrating that modeling multiple levels of abstraction can improve generation with little additional overhead."}],"related":[]},{"id":"guo2026cola2","short":"Cola2","cat":"latent","title":"Cola2: Co-Adaptive Hierarchical Language Modeling with Continuous Semantic Compression and Balanced Discrete Generation","authors":["Hongcan Guo","Yian Zhao","Feng Wang","Shen Nie","Guoqiang Wei","Yan Zeng","Hengshuang Zhao"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.31305","arxiv":"2610.31305","code":null,"overview":"Cola2 studies continuous semantic compression together with discrete realization. It segments text into semantic spans and co-adapts the latent space with a block-causal masked diffusion decoder.","n":1,"x":159.8,"y":391.6,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"Cola2 learns segmentation into variable-length spans, allowing the number of tokens represented by each latent to depend on the text."}],"related":[]},{"id":"he2026rethinking","short":"PSF","cat":"latent","title":"Rethinking the Roles of Diffusion and Decoding: Predictive-State Flows for Parallel Language Generation","authors":["Jinjin He","Xinsong Feng","Lucheng Fu","Sinan Wang","Bo Zhu","Jiayun Wang"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.12898","arxiv":"2610.12898","code":null,"overview":"PSF divides the generative work. The diffusion prior generates high-level predictive information for each block, and the decoder resolves the remaining token-level choices.","n":1,"x":87.7,"y":369.3,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"PSF uses a flow to model states computed from the context preceding each block."}],"related":[]},{"id":"barrault2024large","short":"LCM","cat":"latent","title":"Large Concept Models: Language Modeling in a Sentence Representation Space","authors":["Loïc Barrault","Paul-Ambroise Duquenne","Maha Elbayad","Artyom Kozhevnikov","Belen Alastruey","Pierre Andrews","Mariano Coria","Guillaume Couairon","Marta R. Costa-jussà","David Dale","et al."],"venue":"arXiv","year":2024,"url":"https://arxiv.org/abs/2412.08821","arxiv":"2412.08821","code":"https://github.com/facebookresearch/large_concept_model","overview":"Large Concept Models operate on an explicit higher-level semantic representation at the level of sentences, rather than on tokens.","n":2,"x":118.7,"y":275.3,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"Large Concept Model (LCM) instead generates sentence embeddings in the space of SONAR, conditioning each on the previous ones, and decodes them with its frozen SONAR decoder."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.1 Early Attempts at Scaling","text":"LCM trains a 7B model from scratch, generating sentence embeddings by diffusion and decoding them with a frozen AR decoder (Section 3.1.4)."}],"related":[]},{"id":"peng2026don","short":"Representation Alignment","cat":"latent","title":"Don't Retrain, Align: Adapting Autoregressive LMs to Diffusion LMs via Representation Alignment","authors":["Fred Zhangzhi Peng","Alexis Fox","Anru R Zhang","Alexander Tong"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.06885","arxiv":"2605.06885","code":"https://github.com/pengzhangzhi/Open-dLLM","overview":"The authors adapt autoregressive checkpoints to diffusion models by aligning internal representations, rather than transferring parameters alone. Denoiser features align with those of a frozen teacher.","n":1,"x":158.5,"y":306.7,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.2.2 Tasks and Evaluation for Large Models","text":"It adds representation alignment (REPA), which aligns intermediate features of the denoiser with the clean representations of a frozen AR teacher, and joint denoising of the sequence and a global latent (REG)."}],"related":[]},{"id":"zhu2025segment","short":"SLD","cat":"latent","title":"Segment-Level Diffusion: A Framework for Controllable Long-Form Generation with Diffusion Language Models","authors":["Xiaochen Zhu","Georgi Karadzhov","Chenxi Whitehouse","Andreas Vlachos"],"venue":"ACL","year":2025,"url":"https://arxiv.org/abs/2412.11333","arxiv":"2412.11333","code":"https://github.com/SpaceHunterInf/Segment_Level_Diffusion","overview":"Segment-Level Diffusion targets long-form generation. It splits the output into multiple latent segments and decodes them with an autoregressive decoder, which simplifies diffusion and improves scalability.","n":1,"x":97.0,"y":314.8,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"SLD similarly decodes one latent per segment of a long output with an AR decoder."}],"related":[]},{"id":"han2023ssd","short":"SSD-LM","cat":"simplex","title":"Ssd-lm: Semi-autoregressive simplex-based diffusion language model for text generation and modular control","authors":["Xiaochuang Han","Sachin Kumar","Yulia Tsvetkov"],"venue":"ACL","year":2023,"url":"https://arxiv.org/abs/2210.17432","arxiv":"2210.17432","code":"https://github.com/xhan77/ssd-lm","overview":"SSD-LM generates blocks of text semi-autoregressively and diffuses on the vocabulary space instead of a learned latent space, so off-the-shelf classifiers can guide it directly.","n":5,"x":659.0,"y":118.1,"r":7.3,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"SSD-LM represents data tokens by logit vectors whose softmax is approximately one-hot and adds Gaussian noise to these logits, with the denoiser receiving their softmax as input."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"SSD-LM passes soft token predictions through a pretrained text classifier's embedding layer and updates the predicted logits along the classifier gradient."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.1 Early Attempts at Scaling","text":"SSD-2 scales SSD-LM up to 13B parameters, initializing from pretrained OPT models."},{"part":"2 Motivations and Preliminaries","secTitle":"2.3 Difficulty of Controllable Generation","text":"Early continuous language models already used these ideas to steer text generation."}],"related":["li2022diffusion"]},{"id":"han2024david","short":"SSD-2","cat":"simplex","title":"David helps goliath: Inference-time collaboration between small specialized and large general diffusion lms","authors":["Xiaochuang Han","Sachin Kumar","Yulia Tsvetkov","Marjan Ghazvininejad"],"venue":"NAACL","year":2024,"url":"https://arxiv.org/abs/2305.14771","arxiv":"2305.14771","code":null,"overview":"The authors scale SSD-LM from 0.4B to 13B parameters and finetune it to follow instructions. SSD-2 then lets a small specialist diffusion model guide a large general model at inference time.","n":3,"x":634.5,"y":108.8,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"SSD-2 uses causal attention for the clean prefix and bidirectional attention within the block being generated, allowing multiple blocks to be trained in parallel against their preceding context."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.1 Early Attempts at Scaling","text":"SSD-2 scales SSD-LM up to 13B parameters, initializing from pretrained OPT models."},{"part":"8 Challenges and Future Directions","secTitle":"8.2 Scaling Pretraining and Few-Step Distillation","text":"Continuous language models around the 10B-parameter scale have largely been built by adapting pretrained AR models, while the token-level and blockwise continuous models surveyed here have been trained from scratch at up to 3B parameters."}],"related":["yang2026large","chavan2026large"]},{"id":"mahabadi2024tess","short":"TESS","cat":"simplex","title":"Tess: Text-to-text self-conditioned simplex diffusion","authors":["Rabeeh Karimi Mahabadi","Hamish Ivison","Jaesung Tae","James Henderson","Iz Beltagy","Matthew E Peters","Arman Cohan"],"venue":"EACL","year":2024,"url":"https://arxiv.org/abs/2305.08379","arxiv":"2305.08379","code":"https://github.com/allenai/tess-diffusion","overview":"TESS is a fully non-autoregressive text diffusion model. It diffuses in logit simplex space instead of a learned embedding space and uses a new form of self-conditioning.","n":4,"x":632.0,"y":151.5,"r":7.0,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"TESS uses the same approach and feeds back its previous vocabulary prediction for self-conditioning (Section 3.4)."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"TESS feeds back the previous token distribution, averaging it with the distribution obtained from the current noisy logits."},{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"TESS generates on a fixed-length canvas and learns to fill unused positions with padding tokens."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.1 Early Attempts at Scaling","text":"Similarly, TESS 2 scales TESS to 7B parameters by adapting a pretrained Mistral-7B."}],"related":[]},{"id":"tae2025tess2","short":"TESS 2","cat":"simplex","title":"TESS 2: A Large-Scale Generalist Diffusion Language Model","authors":["Jaesung Tae","Hamish Ivison","Sachin Kumar","Arman Cohan"],"venue":"ACL","year":2025,"url":"https://arxiv.org/abs/2502.13917","arxiv":"2502.13917","code":"https://github.com/hamishivi/tess-2","overview":"TESS 2 is an instruction-following diffusion model that adapts a strong autoregressive model through continued pretraining. The authors also propose reward guidance, which aligns outputs at inference time without retraining.","n":2,"x":645.9,"y":172.3,"r":6.27,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"TESS 2 extends this interface to reward models."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.1 Early Attempts at Scaling","text":"Similarly, TESS 2 scales TESS to 7B parameters by adapting a pretrained Mistral-7B."}],"related":[]},{"id":"graves2023bayesian","short":"BFN","cat":"simplex","title":"Bayesian Flow Networks","authors":["Alex Graves","Rupesh Kumar Srivastava","Timothy Atkinson","Faustino Gomez"],"venue":"arXiv","year":2023,"url":"https://arxiv.org/abs/2308.07037","arxiv":"2308.07037","code":"https://github.com/nnaisense/bayesian-flow-networks","overview":"Bayesian Flow Networks update the parameters of independent distributions with Bayesian inference and pass them through a neural network. This gives a generative procedure with no forward process, and discrete data stays on the probability simplex.","n":1,"x":660.4,"y":92.9,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"Other approaches define updates directly on the simplex, with early approaches including Bayesian probabilistic updates in BFN."}],"related":[]},{"id":"stark2024dirichlet","short":"Dirichlet FM","cat":"simplex","title":"Dirichlet Flow Matching with Applications to DNA Sequence Design","authors":["Hannes Stark","Bowen Jing","Chenyu Wang","Gabriele Corso","Bonnie Berger","Regina Barzilay","Tommi Jaakkola"],"venue":"ICML","year":2024,"url":"https://arxiv.org/abs/2402.05841","arxiv":"2402.05841","code":"https://github.com/HannesStark/dirichlet-flow-matching","overview":"Dirichlet FM uses mixtures of Dirichlet distributions as probability paths, because linear flow matching on the simplex has discontinuous targets. It supports guidance and one-step distilled generation for DNA design.","n":4,"x":817.3,"y":69.8,"r":7.0,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.2 Conditional Generation and Reward Guidance","text":"Dirichlet FM adapts both classifier-free and classifier-based guidance to guide promoter DNA design toward higher regulatory activity, as predicted by Chen et al.."},{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"Dirichlet Flow Matching shows that straight-line interpolation from simplex noise to token vertices produces shrinking conditional supports and discontinuous velocity fields."},{"part":"7 Applications and Evaluation","secTitle":"7.4.1 Tasks and Datasets","text":"This has motivated new approaches to protein, peptide, DNA, and RNA sequence design and to small-molecule generation, including discrete diffusion, discrete flows, continuous flows over probabilities or over protein language model encodings, and flow maps."},{"part":"7 Applications and Evaluation","secTitle":"7.4.3 Evaluation Metrics","text":"Protein design can be evaluated using predicted structural confidence and sequence-structure consistency, peptide design using predicted binding affinity, predicted properties, and docking scores, small-molecule design using Fréchet ChemNet Distance (FCD), and DNA/RNA design using predicted regulatory activity or Fréchet Biological Distance (FBD)."}],"related":["tang2025gumbel","davis2024fisher"]},{"id":"avdeyev2023dirichlet","short":"DDSM","cat":"simplex","title":"Dirichlet diffusion score model for biological sequence generation","authors":["Pavel Avdeyev","Chenlai Shi","Yuhao Tan","Kseniia Dudnyk","Jian Zhou"],"venue":"ICML","year":2023,"url":"https://arxiv.org/abs/2305.10699","arxiv":"2305.10699","code":"https://github.com/jzhoulab/ddsm","overview":"DDSM defines a diffusion process on the probability simplex whose stationary distribution is Dirichlet, which makes continuous diffusion natural for biological sequences.","n":1,"x":803.9,"y":90.5,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.3 Evaluation Metrics","text":"Protein design can be evaluated using predicted structural confidence and sequence-structure consistency, peptide design using predicted binding affinity, predicted properties, and docking scores, small-molecule design using Fréchet ChemNet Distance (FCD), and DNA/RNA design using predicted regulatory activity or Fréchet Biological Distance (FBD)."}],"related":[]},{"id":"tang2025gumbel","short":"Gumbel-Softmax FM","cat":"simplex","title":"Gumbel-Softmax Flow Matching with Straight-Through Guidance for Controllable Biological Sequence Generation","authors":["Sophia Tang","Yinuo Zhang","Alexander Tong","Pranam Chatterjee"],"venue":"arXiv","year":2025,"url":"https://arxiv.org/abs/2503.17361","arxiv":"2503.17361","code":null,"overview":"Gumbel-Softmax FM uses an interpolant with a time-dependent temperature so that simplex flows scale to peptides and proteins. Straight-through guidance then steers generation.","n":4,"x":791.4,"y":69.3,"r":7.0,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.2 Conditional Generation and Reward Guidance","text":"Similarly, Gumbel-Softmax FM introduces STGFlow, which samples discrete sequences at intermediate timesteps and applies the straight-through estimator to guide peptide generation toward target binding affinity."},{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"Gumbel-Softmax Flow Matching uses another family of paths, sharpening initially diffuse token distributions as the temperature decreases."},{"part":"7 Applications and Evaluation","secTitle":"7.4.1 Tasks and Datasets","text":"This has motivated new approaches to protein, peptide, DNA, and RNA sequence design and to small-molecule generation, including discrete diffusion, discrete flows, continuous flows over probabilities or over protein language model encodings, and flow maps."},{"part":"7 Applications and Evaluation","secTitle":"7.4.3 Evaluation Metrics","text":"Protein design can be evaluated using predicted structural confidence and sequence-structure consistency, peptide design using predicted binding affinity, predicted properties, and docking scores, small-molecule design using Fréchet ChemNet Distance (FCD), and DNA/RNA design using predicted regulatory activity or Fréchet Biological Distance (FBD)."}],"related":["stark2024dirichlet","davis2024fisher"]},{"id":"davis2024fisher","short":"Fisher-Flow","cat":"simplex","title":"Fisher Flow Matching for Generative Modeling over Discrete Data","authors":["Oscar Davis","Samuel Kessler","Mircea Petrache","\\.Ismail \\.Ilkan Ceylan","Michael Bronstein","Avishek Joey Bose"],"venue":"NeurIPS","year":2024,"url":"https://arxiv.org/abs/2405.14664","arxiv":"2405.14664","code":"https://github.com/olsdavis/fisher-flow","overview":"Fisher-Flow treats categorical distributions as points on a statistical manifold with the Fisher-Rao metric, and it trains flow matching on that geometry.","n":2,"x":718.1,"y":55.7,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.6 Spherical Representations","text":"Fisher-Flow uses this connection to train with Riemannian flow matching along spherical geodesics."},{"part":"7 Applications and Evaluation","secTitle":"7.4.1 Tasks and Datasets","text":"This has motivated new approaches to protein, peptide, DNA, and RNA sequence design and to small-molecule generation, including discrete diffusion, discrete flows, continuous flows over probabilities or over protein language model encodings, and flow maps."}],"related":["tang2025gumbel","stark2024dirichlet"]},{"id":"jo2026continuous","short":"RDLM","cat":"simplex","title":"Continuous Diffusion Model for Language Modeling","authors":["Jaehyeong Jo","Sung Ju Hwang"],"venue":"NeurIPS","year":2025,"url":"https://arxiv.org/abs/2502.11564","arxiv":"2502.11564","code":"https://github.com/harryjo97/RDLM","overview":"RDLM builds continuous diffusion on the geometry of the categorical distribution, using a statistical manifold. The authors connect it to discrete diffusion, so continuous models keep their signal between steps.","n":2,"x":678.5,"y":78.8,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.6 Spherical Representations","text":"RDLM constructs stochastic bridges toward token vertices on the hypersphere, combining their drifts according to predicted token probabilities."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"Bidirectional transformers are the most common architectural choice, as in CDCD and RDLM."}],"related":["dieleman2022continuous"]},{"id":"deschenaux2026simplex","short":"SDM","cat":"simplex","title":"Simplex Diffusion Models","authors":["Justin Deschenaux","Alexandre Galashov","Andrew Campbell","Li Kevin Wenliang","James Thornton","Arnaud Doucet","Valentin De Bortoli"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.35553","arxiv":"2609.35553","code":null,"overview":"SDM lifts diffusion to the probability simplex to keep beliefs over categories at each step. It has closed-form reverse transitions, trains with cross-entropy, and uses a DDIM-like sampler.","n":6,"x":618.5,"y":74.0,"r":7.56,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"Simplex Diffusion Models (SDM) separately control the mean and concentration of their Dirichlet paths and derive closed-form reverse transitions, allowing sampling with adjustable stochasticity without integrating an ODE."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"SDM leverages hidden features from the preceding network evaluation, allowing feedback to retain information beyond the clean prediction."},{"part":"4 Inference Strategies","secTitle":"4.1 Sampling and Time Allocation","text":"Spherical Flows project numerical updates back onto the sphere, while SDM uses reverse transitions that remain on the simplex."},{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"SDM uses an earlier checkpoint and applies guidance to logits before the softmax."}],"related":["deschenaux2026language","suleymanzade2026thinking","pynadath2025candi","lee2026flow","chemseddine2026spherical","bansal2026token"]},{"id":"deschenaux2026language","short":"S-FLM","cat":"simplex","title":"Language modeling with hyperspherical flows","authors":["Justin Deschenaux","Caglar Gulcehre"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.11125","arxiv":"2605.11125","code":"https://github.com/jdeschena/s-flm","overview":"S-FLM moves flow language models from high-dimensional one-hot vectors to hyperspherical embeddings. This lowers training cost and gives noise a more semantic meaning.","n":4,"x":616.0,"y":47.7,"r":7.0,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.6 Spherical Representations","text":"S-FLM trains on geodesic interpolations between uniform spherical noise and clean embeddings."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.2 Adapting Pretrained Models","text":"LLaCO adapts the AR–diffusion hybrid model NLD to continuous states at 8B parameters, and it follows spherical geodesics as in S-FLM (Section 3.1.6) but toward a noise endpoint that is biased to the mask embedding."},{"part":"7 Applications and Evaluation","secTitle":"7.2.1 Tasks and Evaluation for Small Models","text":"Hybrid models such as CANDI and standard one-hot flows like FLM perform poorly, whereas S-FLM closes the gap to discrete diffusion and SDM outperforms them."},{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"Sudoku is the most common of these benchmarks for continuous language models, usually evaluated at four difficulty levels."}],"related":["deschenaux2026simplex","suleymanzade2026thinking","pynadath2025candi","lee2026flow","bansal2026token"]},{"id":"chemseddine2026spherical","short":"Spherical Flows","cat":"simplex","title":"Spherical Flows for Sampling Categorical Data","authors":["Jannis Chemseddine","Gregor Kornhardt","Gabriele Steidl"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.05629","arxiv":"2605.05629","code":"https://github.com/JChemseddine/SFCD","overview":"Spherical Flows generate discrete sequences on the sphere, where the von Mises-Fisher distribution gives a natural noise process. The authors reduce the conditional velocity to a scalar ODE.","n":2,"x":620.7,"y":22.7,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.6 Spherical Representations","text":"Spherical Flows uses von Mises–Fisher paths, which progress from uniform noise to increasingly concentrated distributions around each target embedding."},{"part":"4 Inference Strategies","secTitle":"4.1 Sampling and Time Allocation","text":"Spherical Flows project numerical updates back onto the sphere, while SDM uses reverse transitions that remain on the simplex."}],"related":["deschenaux2026simplex"]},{"id":"miele2026spherical","short":"SBD","cat":"simplex","title":"Spherical Brownian Diffusion for Language Modeling","authors":["Andrea Miele","Ilija Bogunovic"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.35101","arxiv":"2610.35101","code":null,"overview":"SBD uses Brownian motion as the forward process on the sphere, with a clean-token posterior learned by cross-entropy. The authors separate how much the forward process matters from how much the sampler matters.","n":1,"x":639.0,"y":36.6,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.6 Spherical Representations","text":"SBD uses Brownian motion on the sphere to corrupt token embeddings."}],"related":[]},{"id":"jia2026llaco","short":"LLaCO","cat":"simplex","title":"LLaCO: Continuous Diffusion for Large Language Models with Competition-Aware Semantic Scheduling","authors":["Zijian Jia","Peixuan Zhang","Genying Li","Di Wu","Yujie Fu","Si Li","Boxin Shi","Shuchen Weng"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.32604","arxiv":"2610.32604","code":"https://github.com/WhenGIX/LLaCO","overview":"LLaCO adapts continuous diffusion to large language models. Its Competition Threshold Theory explains how embedding norm decay misaligns the trajectory with time, and it evaluates token competition directionally.","n":1,"x":639.2,"y":59.4,"r":5.75,"mentions":[{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.2 Adapting Pretrained Models","text":"LLaCO adapts the AR–diffusion hybrid model NLD to continuous states at 8B parameters, and it follows spherical geodesics as in S-FLM (Section 3.1.6) but toward a noise endpoint that is biased to the mask embedding."}],"related":[]},{"id":"lee2026flow","short":"FLM / FMLM","cat":"onehot","title":"Flow map language models: One-step language modeling via continuous denoising","authors":["Chanhyuk Lee","Jaehoon Yoo","Manan Agarwal","Sheel Shah","Jerry Huang","Aditi Raghunathan","Seunghoon Hong","Nicholas M Boffi","Jinwoo Kim"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2602.16813","arxiv":"2602.16813","code":"https://github.com/david3684/flm","overview":"FLM trains continuous flows over one-hot tokens with cross-entropy, and FMLM learns the associated flow map for few-step generation. Discrete methods lack this flow map, and the authors show better quality and speed than discrete diffusion.","n":21,"x":761.0,"y":288.8,"r":10.23,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.2.1 Prediction Parameterizations","text":"In FLM, Lee et al. find that this makes velocity prediction difficult in one-hot spaces where the vocabulary dimension greatly exceeds the network's hidden width."},{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"The evolving state lies in the ambient space $\\mathbb{R}^V$, while the optimal denoiser lies on the probability simplex, since … Its coordinates are therefore token probabilities, which can be parameterized by a softmax and learned with cross-entropy, as in CatFlow and Flow Language Models (FLM)."},{"part":"3 Continuous Language Models","secTitle":"3.2.2 Cross-Entropy Objectives","text":"FLM thus learns its denoiser $D^\\theta=q^\\theta$ with cross-entropy and obtains the velocity through Equation."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"FLM retains the linear interpolant and samples times through a time reparameterization in which the recovery probability increases linearly."}],"related":["tang2026discrete","potaptchik2026discrete","chen2026langflow","hu2026elf","roos2026categorical","pynadath2025candi","deschenaux2026simplex","deschenaux2026language"]},{"id":"roos2026categorical","short":"CFM","cat":"onehot","title":"Categorical flow maps","authors":["Daan Roos","Oscar Davis","Floor Eijkelboom","Michael Bronstein","Max Welling","Ismail Ilkan Ceylan","Luca Ambrogioni","Jan-Willem van de Meent"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2602.12233","arxiv":"2602.12233","code":"https://github.com/olsdavis/semicat","overview":"Categorical Flow Maps accelerate few-step generation of categorical data through self-distillation. A flow map toward the simplex constrains predictions, and a new endpoint consistency objective trains it.","n":7,"x":770.5,"y":319.7,"r":7.81,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.3 Two-Time Denoisers","text":"Categorical Flow Maps (CFM) and Flow Map Language Models (FMLM) concurrently introduced, and Discrete Flow Maps (DFM) further developed, a reparameterization of the flow map through a two-time denoiser $\\delta_{s,t}$, also called the mean denoiser, … Comparing with, the two-time denoiser is the clean estimate that a single straight step must use in place of $D_s$ to land exactly on the trajectory at time $t$."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.1 Training Flow Maps","text":"CFM instead trains the off-diagonal with endpoint-consistent Lagrangian distillation, a cross-entropy consistency term on the endpoint prediction combined with a penalty on its time derivative, which together bound the Lagrangian residual."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"CFM, DFM, the scaled CFM of Davis et al., and FMLM+ instead learn the denoiser from data and distill it within the same model, either jointly or in a second stage, so that no separate teacher is needed."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.4.2 Guiding the Flow Map","text":"CFM applies the same idea to categorical image generation."}],"related":["tang2026discrete","potaptchik2026discrete","lee2026flow"]},{"id":"davis2026scaling","short":"Scaling CFM","cat":"onehot","title":"Scaling Categorical Flow Maps","authors":["Oscar Davis","Anastasiia Filippova","Pierre Ablin","Victor Turrisi","Amitis Shidani","Marco Cuturi","Louis Béthune"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.07820","arxiv":"2605.07820","code":null,"overview":"The authors train a 1.7B flow model and self-distill it into a categorical flow map that generates diverse text in few steps, which answers whether this approach scales past 1B parameters.","n":6,"x":749.9,"y":338.8,"r":7.56,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"CFM, DFM, the scaled CFM of Davis et al., and FMLM+ instead learn the denoiser from data and distill it within the same model, either jointly or in a second stage, so that no separate teacher is needed."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.1 Training from Scratch","text":"Davis et al. scale one-hot-based CFM (Section 5.1) to 1.7B parameters through design-space studies and hyperparameter searches over the time schedule, loss weighting, and optimizer settings."},{"part":"1 Introduction","secTitle":"","text":"Continuous language models now match or surpass strong discrete baselines on generation benchmarks, and have been scaled to billions of parameters."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.1 Training Flow Maps","text":"While existing work finds the semigroup form preferable for one-step quality, a universally optimal objective is yet to be settled."}],"related":["yang2026large","yang2026continuous","potaptchik2026discrete","lee2026flow","guo2026continuous","gulrajani2023likelihood","draxler2026parallel2","chen2026langflow"]},{"id":"potaptchik2026discrete","short":"DFM","cat":"onehot","title":"Discrete flow maps","authors":["Peter Potaptchik","Jason Yim","Adhi Saravanan","Peter Holderrieth","Eric Vanden-Eijnden","Michael S Albergo"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2604.09784","arxiv":"2604.09784","code":null,"overview":"Discrete Flow Maps reconcile trajectory compression with the geometry of the simplex, replacing the Euclidean regression losses that suit discrete data poorly.","n":7,"x":742.2,"y":313.1,"r":7.81,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.3 Two-Time Denoisers","text":"Categorical Flow Maps (CFM) and Flow Map Language Models (FMLM) concurrently introduced, and Discrete Flow Maps (DFM) further developed, a reparameterization of the flow map through a two-time denoiser $\\delta_{s,t}$, also called the mean denoiser, … Comparing with, the two-time denoiser is the clean estimate that a single straight step must use in place of $D_s$ to land exactly on the trajectory at time $t$."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.1 Training Flow Maps","text":"DFM rewrites all three conditions- as fixed-point equations for $\\delta_{s,t}$, constructing the Lagrangian and Eulerian targets in logit space since they can leave the simplex."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"CFM, DFM, the scaled CFM of Davis et al., and FMLM+ instead learn the denoiser from data and distill it within the same model, either jointly or in a second stage, so that no separate teacher is needed."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"Potaptchik et al. implement the same principle through the noise schedule, choosing the interpolant coefficients so that the recovery probability increases approximately linearly with time."}],"related":["lee2026flow","tang2026discrete","roos2026categorical","davis2026scaling"]},{"id":"tang2026discrete","short":"DBTM","cat":"onehot","title":"Discrete Beckmann Transport Models for One-Step Language Modeling and Reasoning","authors":["Sophia Tang","Shiyi Wang"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.15903","arxiv":"2609.15903","code":"https://github.com/sophtang/DBTM","overview":"DBTM learns a time-independent flow whose transport map carries any point to a simplex vertex in one step. A conservation equation trains it directly from data, with no teacher and no time conditioning.","n":10,"x":860.8,"y":214.5,"r":8.45,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.5 Autonomous Endpoint Maps","text":"Discrete Beckmann Transport Models (DBTM) bring this framework to language with ambient flows toward one-hot vectors and a per-position softmax parameterization."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.4 Training Autonomous Endpoint Maps","text":"Since $b$ enters linearly and $b(\\boldsymbol{x})=\\mathbb{E}[\\dot I_t\\mid I_t=\\boldsymbol{x}]$, the per-sample velocity of the interpolant $\\dot I_t$ can replace it within the expectation, and DBTM minimizes the error of a stop-gradient fixed-point iteration, … where the directional derivative is computed with JVP and the stationary points satisfy $b\\cdot\\nabla T=0$."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"Suitable couplings between noise and data for one-step generation can also be learned, like in Coupling Models, which fit an encoder and a normalizing flow that pair each sequence with a Gaussian latent to train a one-step decoder, or defined with the model itself, like DBTM, which match noise with targets produced by the model's own rollouts."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.3 Sampling with Learned Maps","text":"DBTM, for example, fixes selected tokens as context and replaces unresolved positions with fresh noise before applying the map again."}],"related":["lee2026flow","potaptchik2026discrete","lee2026asynchronous","agarwal2026posterior","roos2026categorical"]},{"id":"tang2026expanding","short":"EFlows / EFM","cat":"onehot","title":"Expanding Flow Maps","authors":["Sophia Tang","Pranam Chatterjee"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2607.21585","arxiv":"2607.21585","code":null,"overview":"Expanding Flow Maps define flows between distributions of increasing dimension, so sequence length can grow during generation. Each map splits into expand and flow operations for few-step models.","n":2,"x":915.1,"y":259.7,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Expanding Generative Flows (EFlows) insert new positions initialized with Gaussian noise and continuously refine the growing sequence."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"Expanding Flow Maps (EFM) further support sequences that grow during generation, combining insertion of new noisy positions with learned transport of the representations."}],"related":[]},{"id":"lee2026asynchronous","short":"aFLM / aFMLM","cat":"onehot","title":"Asynchronous Flow Map Language Models","authors":["Chanhyuk Lee","Wonjung Kim","Patrick Pynadath","Jaehoon Yoo","Satoshi Hayakawa","Ruqi Zhang","Jinwoo Kim","Seunghoon Hong"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.42018","arxiv":"2610.42018","code":"https://github.com/david3684/async-fmlm","overview":"aFLM and aFMLM bring prediction order into one-step generation. Tokenwise time schedules control the relative denoising progress of each token, and the schedules can be prescribed or learned.","n":5,"x":899.6,"y":204.4,"r":7.3,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"TTCD chooses an ordering from the initial denoising prediction, whereas the flows underlying Asynchronous FLM (aFLM) can adjust tokenwise progress throughout generation."},{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"The asynchronous flows underlying aFLM instead update priorities throughout generation using tokenwise time schedules adapted from unmasking strategies of masked diffusion models."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"Asynchronous FMLM (aFMLM) learns maps of asynchronous flows with prescribed or prediction-dependent tokenwise schedules."},{"part":"7 Applications and Evaluation","secTitle":"7.2.1 Tasks and Evaluation for Small Models","text":"Furthermore, FMLM+, DBTM, and aFMLM reach strong accuracy with one or a few function evaluations."}],"related":["tang2026discrete","agarwal2026posterior"]},{"id":"yoo2026self","short":"FMLM*","cat":"onehot","title":"Self-conditioned Flow Map Language Models via Fixed-point Flows","authors":["Jaehoon Yoo","Wonjung Kim","Floor Eijkelboom","Chanhyuk Lee","Nicholas M Boffi","Seunghoon Hong","Jinwoo Kim"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2607.00714","arxiv":"2607.00714","code":"https://github.com/Ugness/self-conditioned-fmlm","overview":"The authors show that self-conditioned flow language models perform a fixed-point iteration. Fixed-point flows use this view to carry self-conditioning into few-step flow map models.","n":8,"x":871.7,"y":286.1,"r":8.04,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"FMLM$^\\star$ and ELF-REG use causal hidden states from GPT-2 and Qwen, respectively, while MF-1 applies T5 independently within short token blocks."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Plaid and Fixed-Point Flows interpret self-conditioning through fixed-point refinement."},{"part":"4 Inference Strategies","secTitle":"4.3 Self-Conditioning and Iterative Refinement","text":"Fixed-Point Flows interpret this as a fixed-point iteration that refines the feedback prediction while holding the state and time fixed, … where $j$ indexes inner iterations and $0<\\eta\\leq1$."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.3 Two-Time Denoisers","text":"The same parameterization applies in learned embedding and latent spaces, where $\\delta_{s,t}$ predicts a clean embedding and is trained by regression."}],"related":["semenov2026latent","li2026elf","hu2026elf","gulrajani2023likelihood"]},{"id":"agarwal2026posterior","short":"FMLM+","cat":"onehot","title":"Posterior Refinement: Fast Language Generation via Any-Order Flow Maps","authors":["Manan Agarwal","Sheel Shah","Chanhyuk Lee","Jaehoon Yoo","Jerry Huang","Seunghoon Hong","Aditi Raghunathan","Jinwoo Kim","Nicholas M Boffi"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.24773","arxiv":"2606.24773","code":"https://github.com/MananAg007/posterior-refinement","overview":"FMLM+ equips flow map language models with masking-style noise schedules. It generates a full sequence in one step and can also critique, erase, and regenerate subsets of tokens.","n":5,"x":838.1,"y":230.5,"r":7.3,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"CFM, DFM, the scaled CFM of Davis et al., and FMLM+ instead learn the denoiser from data and distill it within the same model, either jointly or in a second stage, so that no separate teacher is needed."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"With this, FMLM+ and DBTM train with a partial-context interpolant with a random subset of positions clean at $t=1$ and the rest at a shared intermediate time."},{"part":"7 Applications and Evaluation","secTitle":"7.2.1 Tasks and Evaluation for Small Models","text":"Furthermore, FMLM+, DBTM, and aFMLM reach strong accuracy with one or a few function evaluations."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"This makes any-order sampling possible with clean context conditioning, and can be initialized from a pretrained masked model."}],"related":["tang2026discrete","lee2026asynchronous"]},{"id":"azangulov2026masked","short":"MLFM","cat":"onehot","title":"Masked Language Flow Models","authors":["Iskander Azangulov","Kianoosh Ashouritaklimi","Leo Zhang","Simon Vary","Patrick Rebeschini"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.27617","arxiv":"2606.27617","code":"https://github.com/imbirik/mlfm","overview":"MLFM incorporates masking into flow language models, which otherwise must decode every token during generation. This makes multi-step reasoning tasks easier to handle.","n":3,"x":937.0,"y":272.8,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Masked Language Flow Models (MLFM) learn to denoise undecided positions while keeping observed tokens at their clean embeddings."},{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"MLFM commits positions whose maximum token probability exceeds a threshold, replacing their states with clean token embeddings."},{"part":"7 Applications and Evaluation","secTitle":"7.2.2 Tasks and Evaluation for Large Models","text":"MLFM adapts pretrained masked diffusion models into flows and is among the first flow language models evaluated on instruction following."}],"related":[]},{"id":"chen2022analog","short":"Analog Bits","cat":"onehot","title":"Analog bits: Generating discrete data using diffusion models with self-conditioning","authors":["Ting Chen","Ruixiang Zhang","Geoffrey Hinton"],"venue":"ICLR","year":2023,"url":"https://arxiv.org/abs/2208.04202","arxiv":"2208.04202","code":"https://github.com/google-research/pix2seq","overview":"Bit Diffusion represents discrete data as binary bits and models them as real numbers with continuous diffusion. The paper also introduces self-conditioning and asymmetric time intervals.","n":2,"x":946.1,"y":330.6,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"Analog Bits introduced diffusion over such codes by treating their bits as real-valued coordinates during generation and thresholding the final predictions back to bits."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Self-conditioning is a simple and effective technique introduced in Analog Bits and subsequently adopted broadly for continuous text generation."}],"related":[]},{"id":"batzolis2026cobit","short":"CoBit","cat":"onehot","title":"CoBit: Language Modeling with Bitstream Diffusion","authors":["Georgios Batzolis","Mark Girolami","Luca Ambrogioni"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.07013","arxiv":"2605.07013","code":"https://github.com/GBATZOLIS/BitstreamDiffusion","overview":"CoBit models text as continuous diffusion over fixed-width binary bitstreams. It uses a matched-filter residual parameterization and a stochastic sampler with Langevin-type corrections.","n":3,"x":974.9,"y":327.8,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"CoBit develops bitstream diffusion for language, grouping bits into transformer inputs and replacing the vocabulary-sized prediction head with a compact bitwise head."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"CoBit applies the same principle to bitstreams through the information-guided allocation of InfoNoise, which estimates how fast this uncertainty changes from denoising errors."},{"part":"4 Inference Strategies","secTitle":"4.1 Sampling and Time Allocation","text":"CoBit finds that the benefit of noise injection depends on the grid, motivating their joint selection."}],"related":[]},{"id":"zhuang2026bitlm","short":"BitLM","cat":"onehot","title":"BitLM: Unlocking Multi-Token Language Generation with Bitwise Continuous Diffusion","authors":["Shaobin Zhuang","Yuang Ai","Jiaming Han","Xiaohui Li","Huaibo Huang","Xiangyu Yue","Xuefeng Hu","Kun Xu","Yali Wang","Hao Chen"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.11577","arxiv":"2605.11577","code":null,"overview":"BitLM represents each token as a binary code and uses a light diffusion head to denoise several tokens in parallel within a block, while keeping left-to-right structure between blocks.","n":2,"x":977.7,"y":351.7,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"BitLM uses binary token codes in a lightweight bitwise head that generates several tokens jointly within each block, while retaining causal attention across blocks."},{"part":"3 Continuous Language Models","secTitle":"3.5 Architecture","text":"BitLM separates a large context-processing backbone from a lightweight diffusion head."}],"related":[]},{"id":"eijkelboom2024variational","short":"CatFlow","cat":"onehot","title":"Variational flow matching for graph generation","authors":["Floor Eijkelboom","Grigory Bartosh","Christian A Naesseth","Max Welling","Jan-Willem van de Meent"],"venue":"NeurIPS","year":2024,"url":"https://arxiv.org/abs/2406.04843","arxiv":"2406.04843","code":null,"overview":"This paper formulates flow matching as variational inference and develops CatFlow, a flow matching method for categorical data that the authors evaluate on graph generation.","n":2,"x":896.5,"y":301.6,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.1 One-Hot and Binary Token Encodings","text":"The evolving state lies in the ambient space $\\mathbb{R}^V$, while the optimal denoiser lies on the probability simplex, since … Its coordinates are therefore token probabilities, which can be parameterized by a softmax and learned with cross-entropy, as in CatFlow and Flow Language Models (FLM)."},{"part":"2 Motivations and Preliminaries","secTitle":"2.4 Continuous Processes for Discrete Data","text":"Variational flow matching makes this distinction explicit: for this linear interpolant, even a factorized approximation to the endpoint posterior can recover the exact joint dynamics, provided it matches the per-position conditional means."}],"related":[]},{"id":"oba2026bct","short":"BCT","cat":"onehot","title":"BCT: Bayes-Consistent Tempering for Flow Language Models","authors":["Daisuke Oba","Hiroki Furuta","Naoaki Okazaki"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.27641","arxiv":"2610.27641","code":"https://github.com/daioba/bct","overview":"BCT makes temperature scaling consistent in flow language models. Post-hoc tempering otherwise changes the noisy-state distribution in ways that the denoiser and transport dynamics do not reflect.","n":1,"x":949.5,"y":293.3,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"BCT instead builds temperature into its spherical flows, so that both training and sampling target the tempered distribution."}],"related":[]},{"id":"zhang2024language","short":"LF","cat":"fewstep","title":"LanguageFlow: Advancing Diffusion Language Generation with Probabilistic Flows","authors":["Shujian Zhang","Lemeng Wu","Chengyue Gong","Xingchao Liu"],"venue":"NAACL","year":2024,"url":"https://arxiv.org/abs/2403.16995","arxiv":"2403.16995","code":null,"overview":"LanguageFlow learns ODEs that transport between source and target distributions, which reduces the thousands of denoising steps that diffusion language models otherwise need.","n":1,"x":736.8,"y":590.3,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.1 Reducing Solver Error","text":"FlowSeq trains a velocity field with the same anchor loss and generates with a single Euler step, FMSeq combines embedding denoising, self-conditioning, and a shifted time input to sample in just ten steps, and LF integrates a flow in the latent space of a text autoencoder with ten Euler steps."}],"related":[]},{"id":"hu2024flow","short":"FlowSeq","cat":"fewstep","title":"Flow Matching for Conditional Text Generation in a Few Sampling Steps","authors":["Vincent Tao Hu","Di Wu","Yuki M. Asano","Pascal Mettes","Basura Fernando","Björn Ommer","Cees G. M. Snoek"],"venue":"EACL","year":2024,"url":"https://scholar.google.com/scholar?q=Flow+Matching+for+Conditional+Text+Generation+in+a+Few+Sampling+Steps","arxiv":null,"code":null,"overview":"FlowSeq applies flow matching to conditional text generation. It trains a velocity field with an anchor loss and generates in a single Euler step.","n":1,"x":724.3,"y":609.3,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.1 Reducing Solver Error","text":"FlowSeq trains a velocity field with the same anchor loss and generates with a single Euler step, FMSeq combines embedding denoising, self-conditioning, and a shifted time input to sample in just ten steps, and LF integrates a flow in the latent space of a text autoencoder with ten Euler steps."}],"related":[]},{"id":"liu2024enable","short":"FMSeq","cat":"fewstep","title":"Enable Fast Sampling for Seq2Seq Text Diffusion","authors":["Pan Liu","Xiaohua Tian","Zhouhan Lin"],"venue":"Findings of EMNLP","year":2024,"url":"https://scholar.google.com/scholar?q=Enable+Fast+Sampling+for+Seq2Seq+Text+Diffusion","arxiv":null,"code":null,"overview":"FMSeq speeds up sequence-to-sequence text diffusion. It combines embedding denoising, self-conditioning, and a shifted time input to sample in about ten steps.","n":1,"x":747.3,"y":610.6,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.1 Reducing Solver Error","text":"FlowSeq trains a velocity field with the same anchor loss and generates with a single Euler step, FMSeq combines embedding denoising, self-conditioning, and a shifted time input to sample in just ten steps, and LF integrates a flow in the latent space of a text autoencoder with ten Euler steps."}],"related":[]},{"id":"chen2025dlm","short":"DLM-One","cat":"fewstep","title":"DLM-One: Diffusion Language Models for One-Step Sequence Generation","authors":["Tianqi Chen","Shujian Zhang","Mingyuan Zhou"],"venue":"arXiv","year":2025,"url":"https://arxiv.org/abs/2506.00290","arxiv":"2506.00290","code":null,"overview":"DLM-One trains a student for one-step generation by aligning the scores of its outputs with those of a pretrained teacher. It works on both token embedding and logit simplex spaces.","n":2,"x":935.1,"y":492.9,"r":6.27,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"Examples include DLM-One, Coupling Models, and drifting-type text generators."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"DLM-One applies score identity distillation with an adversarial term to embedding diffusion for sequence-to-sequence tasks."}],"related":[]},{"id":"zhang2026flowlm","short":"FlowLM","cat":"fewstep","title":"FlowLM: Few-Step Language Modeling via Diffusion-to-Flow Adaptation","authors":["Runzhe Zhang","Letian Chen","Wenpeng Zhang","Zhouhan Lin","Peilin Zhao"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.20199","arxiv":"2605.20199","code":null,"overview":"FlowLM turns pretrained diffusion language models into flow matching models by fine-tuning, which straightens curved trajectories for few-step generation. The authors also validate clean-data prediction as the training target.","n":1,"x":840.0,"y":587.5,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.1 Reducing Solver Error","text":"FlowLM later adapted a pretrained embedding diffusion model to the linear interpolant, so that three to five Euler steps suffice."}],"related":[]},{"id":"warczynski2026onestep","short":"Shortcut FM","cat":"fewstep","title":"One-step Nonautoregressive Natural Language Generation with Shortcut Flow Matching Models","authors":["Jedrzej Warczyński","Ondřej Dušek","Mateusz Lango"],"venue":"ACL","year":2026,"url":"https://scholar.google.com/scholar?q=One-step+Nonautoregressive+Natural+Language+Generation+with+Shortcut+Flow+Matching+Models","arxiv":null,"code":null,"overview":"The authors use shortcut modeling to generate natural language in one step without autoregression.","n":1,"x":866.8,"y":583.2,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"Outside the two-time denoiser parameterization, ELF uses progressive distillation to repeatedly cut the number of steps of an embedded flow in half down to one step, Sigma uses parallel decoding distillation to compress large blockwise embedding diffusion into a few steps, and Warczyński et al. use shortcut modeling to learn embedded velocity from data and self-distill it into the average velocity."}],"related":[]},{"id":"peng2026coupling","short":"Coupling Models","cat":"fewstep","title":"Coupling Models for One-Step Discrete Generation","authors":["Fred Zhangzhi Peng","Avishek Joey Bose","Anru R. Zhang","Alexander Tong"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.07193","arxiv":"2605.07193","code":"https://github.com/pengzhangzhi/Coupling-Models","overview":"Coupling Models learn a direct coupling between discrete sequences and Gaussian latents, and a purpose-built decoder inverts it for one-step generation without distilling a teacher.","n":3,"x":917.7,"y":510.3,"r":6.67,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"Examples include DLM-One, Coupling Models, and drifting-type text generators."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"Suitable couplings between noise and data for one-step generation can also be learned, like in Coupling Models, which fit an encoder and a normalizing flow that pair each sequence with a Gaussian latent to train a one-step decoder, or defined with the model itself, like DBTM, which match noise with targets produced by the model's own rollouts."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.4.2 Guiding the Flow Map","text":"Coupling Models use gradient ascent on the latent with respect to a classifier, and apply CFG on the logits of a conditional model."}],"related":[]},{"id":"eijkelboom2026categorical","short":"Categorical Drifting","cat":"fewstep","title":"Categorical Drifting Models","authors":["Floor Eijkelboom","Nabil Iqbal","Max Welling","Jan-Willem van de Meent"],"venue":"ICML Workshop","year":2026,"url":"https://scholar.google.com/scholar?q=Categorical+Drifting+Models","arxiv":null,"code":null,"overview":"Categorical Drifting adapts drifting models to categorical data. A mirror-descent step adds the drift field to the logits, and the model trains with cross-entropy.","n":1,"x":850.8,"y":566.3,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"Categorical Drifting adapts this to categorical data as a mirror-descent step that adds the field to the logits and trains with cross-entropy."}],"related":[]},{"id":"li2026onestep","short":"R-WGF","cat":"fewstep","title":"One-Step Generation via Riemannian Wasserstein Gradient Flows","authors":["David Li","Chanhyuk Lee","Jaehoon Yoo","Nikita Gushchin","Floor Eijkelboom","Eric Moulines","Maxim Panov","Alexander Korotin","Seunghoon Hong","Jinwoo Kim"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.04454","arxiv":"2610.04454","code":null,"overview":"The authors derive and compare geometry-aware drift fields for training one-step generators on constrained spaces, where unconstrained additive updates can leave the valid domain.","n":2,"x":905.0,"y":489.3,"r":6.27,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"R-WGF derives drifting updates as Wasserstein gradient flows on the simplex, and uses them to fine-tune a pretrained flow language model into a one-step generator."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"Examples include DLM-One, Coupling Models, and drifting-type text generators."}],"related":["liu2026onestep"]},{"id":"liu2026onestep","short":"Seq-Drifting","cat":"fewstep","title":"One-Step Text Generation by Seq-Drifting","authors":["Jiayu Liu","Ruizhi Zhao","Tianyun Ji","Yee Whye Teh","Zhenya Huang","Ning Miao"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.12879","arxiv":"2610.12879","code":"https://github.com/jyliu-ai/Seq-Drifting","overview":"Seq-Drifting learns a direct map from Gaussian noise to text. Its attraction and repulsion targets adapt to the context generated at each position.","n":2,"x":922.5,"y":472.7,"r":6.27,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"Seq-Drifting attracts each position toward the likely continuations proposed by a frozen AR model run on the generator's own outputs, with repulsion terms that discourage collapse and repetition."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"Examples include DLM-One, Coupling Models, and drifting-type text generators."}],"related":["li2026onestep"]},{"id":"kim2026gumbel","short":"GSF","cat":"fewstep","title":"Gumbel Straight Flow: Distilling Autoregressive Models into One-step Flow Maps","authors":["Yeongmin Kim","Arnaud Doucet","Andrew Campbell","Valentin De Bortoli","Thomas Mensink","David Ruhe"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.00497","arxiv":"2610.00497","code":null,"overview":"GSF distills an autoregressive model into a one-step flow. The Gumbel coupling from the teacher gives non-intersecting straight paths from noise to one-hot sequences.","n":3,"x":912.8,"y":595.4,"r":6.67,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"FMLM$^\\star$ and CoFlow distill self-conditioned embedded flows (Section 5.5), where CoFlow shows that the embedding itself can be adapted during distillation, and Gumbel Straight Flow (GSF) distills an AR model."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"GSF instead distills an AR model into a flow map of the flow induced by AR coupling."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"Conditional and block-autoregressive flow maps can be interpreted as special cases where a block of tokens is denoised to an intermediate time $t$ while preceding blocks are fixed."}],"related":["yang2026large","chavan2026large"]},{"id":"zhang2026gumbel","short":"Gumbel Distillation","cat":"fewstep","title":"Gumbel Distillation for Parallel Text Generation","authors":["Chi Zhang","Xixi Hu","Bo Liu","Qiang Liu"],"venue":"ICLR","year":2026,"url":"https://arxiv.org/abs/2603.22216","arxiv":"2603.22216","code":"https://github.com/hxixixh/gumbel-distill","overview":"Gumbel Distillation uses the Gumbel-Max trick to map latent noise deterministically to the outputs of an autoregressive teacher, so that parallel decoders can learn the joint distribution of tokens.","n":2,"x":966.1,"y":663.9,"r":6.27,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"The same noise-to-sequence map also appears inside continuous AR models such as CALM, PTP, and Gumbel Distillation, where a prediction head maps continuous noise to the next block of tokens."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"PTP and Gumbel Distillation distill AR into one-step models by directly regressing the noise-to-text mapping given by the AR coupling."}],"related":[]},{"id":"draxler2026parallel","short":"PTP","cat":"fewstep","title":"Parallel Token Prediction for Language Models","authors":["Felix Draxler","Justus Will","Farrin Marouf Sofian","Theofanis Karaletsos","Sameer Singh","Stephan Mandt"],"venue":"ICLR","year":2026,"url":"https://arxiv.org/abs/2512.21323","arxiv":"2512.21323","code":"https://github.com/mandt-lab/ptp","overview":"PTP moves randomness from post-hoc sampling to random inputs, which makes future tokens jointly predictable in a single forward pass. It trains by distillation or by inverse autoregressive training.","n":3,"x":981.2,"y":683.6,"r":6.67,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"The same noise-to-sequence map also appears inside continuous AR models such as CALM, PTP, and Gumbel Distillation, where a prediction head maps continuous noise to the next block of tokens."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.5 Noise-Data Coupling","text":"PTP and Gumbel Distillation distill AR into one-step models by directly regressing the noise-to-text mapping given by the AR coupling."},{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.1 Training from Scratch","text":"In addition, Parallel Language Models (PLMs) train the pushforward generator of PTP, which maps noise to a block of tokens in one forward pass (Section 5.1), from scratch at up to 3B parameters."}],"related":[]},{"id":"shao2025continuous","short":"CALM","cat":"fewstep","title":"Continuous Autoregressive Language Models","authors":["Chenze Shao","Darren Li","Fandong Meng","Jie Zhou"],"venue":"arXiv","year":2025,"url":"https://arxiv.org/abs/2510.27688","arxiv":"2510.27688","code":"https://github.com/shaochenze/calm","overview":"CALM compresses chunks of tokens into continuous vectors with a high-fidelity autoencoder, then predicts the next vector instead of the next token. This reduces the number of generative steps.","n":3,"x":939.7,"y":642.2,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"Manta-LM downsamples the sequence with a convolutional VAE, while CALM represents fixed-size token chunks as individual continuous vectors and generates these vectors autoregressively."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.4 Pushforward Maps","text":"The same noise-to-sequence map also appears inside continuous AR models such as CALM, PTP, and Gumbel Distillation, where a prediction head maps continuous noise to the next block of tokens."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"CALM trains the one-step generation head of its continuous AR model with the energy score, a strictly proper scoring rule that needs only generated and data samples, with no likelihood or teacher."}],"related":[]},{"id":"drobyshevskiy2026representation","short":"Rep-MMD","cat":"fewstep","title":"Representation-Space MMD for Diffusion Language Models","authors":["Ilya Drobyshevskiy","Ilia Sudakov","Maksim Semenov","Denis Kuznedelev","Maksim Ignatov","Pavel Temirchev","Nikita Balagansky","Viacheslav Meshchaninov","Nikita Gushchin","Dmitry Baranchuk"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.06648","arxiv":"2610.06648","code":"https://github.com/yandex-research/dlm-mmd","overview":"Rep-MMD is a post-training method that minimizes Maximum Mean Discrepancy in the feature space of a frozen pretrained model. Continuous models differentiate directly through generated latents.","n":1,"x":899.6,"y":532.1,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"Drobyshevskiy et al. instead minimize the maximum mean discrepancy (MMD) between token-level features of generated and data sequences under a frozen flow language model, which yields a similar attraction-repulsion gradient, and use it to turn embedded flows into one-step generators."}],"related":[]},{"id":"semenov2026latent","short":"CoFlow","cat":"fewstep","title":"Latent Space Co-training for Few-Step Text Generation","authors":["Maksim Semenov","Nikita Balagansky","Ilya Drobyshevskiy","Dmitry Baranchuk","Nikita Gushchin","Daniil Gavrilov","Aibek Alanov","Viacheslav Meshchaninov"],"venue":"NeurIPS Workshop","year":2026,"url":"https://scholar.google.com/scholar?q=Latent+Space+Co-training+for+Few-Step+Text+Generation","arxiv":null,"code":null,"overview":"CoFlow distills a self-conditioned embedded flow and shows that the embedding itself can adapt during distillation, which supports few-step text generation.","n":4,"x":870.6,"y":606.8,"r":7.0,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.2 Distillation and Self-Distillation","text":"FMLM$^\\star$ and CoFlow distill self-conditioned embedded flows (Section 5.5), where CoFlow shows that the embedding itself can be adapted during distillation, and Gumbel Straight Flow (GSF) distills an AR model."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.4.1 Distilling Guided Flow into Flow Map","text":"FMLM$^\\star$ trains a single flow map conditioned on the guidance weight of its self-conditioned teacher, sampling one weight per example and sharing it between teacher and student, and CoFlow incorporates label guidance into the target from which its map is distilled."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.1 Self-Conditioning in Flow Maps","text":"CoFlow applies the same idea in a jointly trained latent space, and other works either keep self-conditioning in a distilled model or disable it."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.3 Two-Time Denoisers","text":"The same parameterization applies in learned embedding and latent spaces, where $\\delta_{s,t}$ predicts a clean embedding and is trained by regression."}],"related":["yoo2026self"]},{"id":"draxler2026parallel2","short":"PLM","cat":"fewstep","title":"Parallel Language Models via Variational Decoding","authors":["Felix Draxler","Robin C Geyer","Daniel Geyfman","Farrin Marouf Sofian","Justus Will","Philipp Hildebrandt","Giosue Migliorini","Prakhar Srivastava","Gagan Sai Trinadh Duggaraju Peddiraju","Kushagra Pandey","et al."],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.26693","arxiv":"2610.26693","code":"https://github.com/mandt-lab/plm","overview":"PLMs generate mutually consistent tokens in one forward pass by routing dependencies through latent auxiliary variables. They train with a variational bound that combines an autoregressive loss and a parallel decoding loss.","n":2,"x":906.6,"y":620.4,"r":6.27,"mentions":[{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.1 Training from Scratch","text":"In addition, Parallel Language Models (PLMs) train the pushforward generator of PTP, which maps noise to a block of tokens in one forward pass (Section 5.1), from scratch at up to 3B parameters."},{"part":"8 Challenges and Future Directions","secTitle":"8.2 Scaling Pretraining and Few-Step Distillation","text":"Continuous language models around the 10B-parameter scale have largely been built by adapting pretrained AR models, while the token-level and blockwise continuous models surveyed here have been trained from scratch at up to 3B parameters."}],"related":["yang2026continuous","guo2026continuous","davis2026scaling"]},{"id":"lee2026beckmann","short":"BTM","cat":"fewstep","title":"Beckmann Transport Models: From Autonomous Flows to One-Step Maps","authors":["Cheuk-Kit Lee","Florentin Coeurdoux","Yuyuan Chen","Sophia Tang","Peter Potaptchik","Yilun Du","Michael S Albergo","Eric Vanden-Eijnden"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2608.01692","arxiv":"2608.01692","code":null,"overview":"Beckmann Transport Models use a time-independent velocity field to map exactly onto singular targets. A conservation equation learns the one-step map directly from samples.","n":1,"x":883.3,"y":567.2,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.1.5 Autonomous Endpoint Maps","text":"Beckmann Transport Models (BTM) replace the time-dependent velocity by the autonomous field obtained by averaging the conditional velocity over time, … which satisfies the divergence constraint $\\nabla\\cdot(\\nu\\, b)=p_0-p_1$ where $\\nu=\\int_0^1p_tdt$."}],"related":[]},{"id":"vankiem2026distribution","short":"S/R-DMD","cat":"fewstep","title":"Distribution Matching Distillation for Continuous Diffusion Language Models","authors":["Paul Le Van Kiem","Dario Shariatian","Umut Simsekli","Alain Durmus"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.40235","arxiv":"2609.40235","code":null,"overview":"The authors study distributional distillation for continuous models. Simplex-DMD uses continuous token relaxations with pathwise gradients, and Reinforce-DMD uses categorical samples with REINFORCE.","n":2,"x":888.7,"y":590.2,"r":6.27,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.2.3 Training Pushforward Maps","text":"Van Kiem et al. apply distribution matching distillation (DMD) to unconditional continuous language models and exploit the student's categorical outputs in two ways."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.3 Sampling with Learned Maps","text":"Van Kiem et al. train such students for continuous language models."}],"related":[]},{"id":"nguyen2026fastdiss","short":"FastDiSS","cat":"fewstep","title":"FastDiSS: Few-step Match Many-step Diffusion Language Model on Sequence-to-Sequence Generation","authors":["Dat Nguyen-Cong","Tung Kieu","Hoang Thanh-Tung"],"venue":"Findings of ACL","year":2026,"url":"https://arxiv.org/abs/2604.05551","arxiv":"2604.05551","code":null,"overview":"FastDiSS shows that inaccurate self-conditioning creates an approximation gap in few-step sampling, and it closes this gap to make few steps match many steps in sequence-to-sequence tasks.","n":1,"x":867.2,"y":551.7,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"TREC and FastDiSS instead modify training, the former keeping self-conditioning beneficial through reinforcement learning and the latter perturbing the self-conditioning input to match the errors of few-step sampling."}],"related":[]},{"id":"sahoo2025diffusion","short":"Duo","cat":"hybrid","title":"The Diffusion Duality","authors":["Subham Sekhar Sahoo","Justin Deschenaux","Aaron Gokaslan","Guanghan Wang","Justin T Chiu","Volodymyr Kuleshov"],"venue":"ICML","year":2025,"url":"https://arxiv.org/abs/2506.10892","arxiv":"2506.10892","code":"https://github.com/s-sahoo/duo","overview":"Duo shows that uniform-state discrete diffusion emerges from an underlying Gaussian diffusion, and it transfers Gaussian techniques to improve discrete training and sampling.","n":2,"x":589.3,"y":392.6,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.5 Simplex Representations","text":"A related idea appears in Duo, which applies tempered softmax on Gaussian diffusion to warm-start the training of uniform discrete diffusion."},{"part":"2 Motivations and Preliminaries","secTitle":"2.2 Factorization Error in Parallel Decoding","text":"This factorization error is therefore a central obstacle to few-step masked diffusion."}],"related":[]},{"id":"pynadath2025candi","short":"CANDI","cat":"hybrid","title":"CANDI: Hybrid Discrete-Continuous Diffusion Models","authors":["Patrick Pynadath","Jiaxin Shi","Ruqi Zhang"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2510.22510","arxiv":"2510.22510","code":null,"overview":"CANDI introduces token identifiability to explain how Gaussian noise corrupts discrete data. It decouples discrete and continuous corruption so that a model can learn both structure and geometry.","n":5,"x":615.1,"y":363.3,"r":7.3,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"CANDI controls discrete masking separately from Gaussian corruption."},{"part":"7 Applications and Evaluation","secTitle":"7.2.1 Tasks and Evaluation for Small Models","text":"Hybrid models such as CANDI and standard one-hot flows like FLM perform poorly, whereas S-FLM closes the gap to discrete diffusion and SDM outperforms them."},{"part":"3 Continuous Language Models","secTitle":"3.1.7 What Makes a Good Representation?","text":"For one-hot encodings, Pynadath et al. and Lee et al. show how vocabulary size affects token identifiability under Gaussian corruption, with the latter allocating training times to the narrow interval where one-hot tokens become distinguishable."},{"part":"3 Continuous Language Models","secTitle":"3.3 Noise Scheduling and Time Reparameterization","text":"For one-hot representations under a linear Gaussian interpolant, for instance, the probability of recovering the clean token by argmax changes sharply within a short time interval, especially for large vocabularies."}],"related":["lee2026flow","deschenaux2026simplex","deschenaux2026language"]},{"id":"zheng2026cadd","short":"CADD","cat":"hybrid","title":"Continuously Augmented Discrete Diffusion Model for Categorical Generative Modeling","authors":["Huangjie Zheng","Shansan Gong","Ruixiang Zhang","Tianrong Chen","Jiatao Gu","Mingyuan Zhou","Navdeep Jaitly","Yizhe Zhang"],"venue":"ICLR","year":2026,"url":"https://arxiv.org/abs/2510.01329","arxiv":"2510.01329","code":"https://github.com/apple-aiml-research/ml-cadd","overview":"CADD pairs discrete diffusion with a diffusion in continuous latent space. Masked tokens become noisy but informative vectors, which can act as semantic hints during denoising.","n":1,"x":657.4,"y":296.3,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Hybrid models build discrete decisions into the generative process itself."}],"related":["zhou2025ccdd"]},{"id":"zhou2025ccdd","short":"CCDD","cat":"hybrid","title":"Coevolutionary Continuous Discrete Diffusion: Make Your Diffusion Language Model a Latent Reasoner","authors":["Cai Zhou","Chenxiao Yang","Yi Hu","Chenyu Wang","Chubin Zhang","Muhan Zhang","Lester Mackey","Tommi Jaakkola","Stephen Bates","Dinghuai Zhang"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2510.03206","arxiv":"2510.03206","code":"https://github.com/zhouc20/CCDD","overview":"CCDD argues that continuous diffusion is more expressive but harder to train than discrete diffusion, so it evolves continuous and discrete states together.","n":1,"x":636.8,"y":287.7,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Hybrid models build discrete decisions into the generative process itself."}],"related":["zheng2026cadd"]},{"id":"lemercier2026diladiff","short":"DiLaDiff","cat":"hybrid","title":"DiLaDiff: Distilled Latent-Augmented Diffusion for Language Modeling","authors":["Jean-Marie Lemercier","Tomas Geffner","Karsten Kreis","Morteza Mardani","Arash Vahdat","Ante Jukić"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.23605","arxiv":"2605.23605","code":null,"overview":"DiLaDiff extends masked diffusion with a continuous semantic latent space and a latent diffusion prior. A consistency model distills that prior for few-step generation.","n":2,"x":467.3,"y":316.2,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"DiLaDiff conditions a masked diffusion decoder on generated continuous latents, using the shared latent information to coordinate its token predictions, and CRoCoDiL obtains such a decoder by fine-tuning a pretrained masked diffusion model jointly with the encoder."},{"part":"2 Motivations and Preliminaries","secTitle":"2.2 Factorization Error in Parallel Decoding","text":"Methods that address this error introduce dependence between sampled positions, for example through a shared latent variable, a model that couples the token predictions, a rectified source-target coupling, or a stochastic mask."}],"related":[]},{"id":"wang2026masked","short":"x-Prediction Flow","cat":"hybrid","title":"$x$-Prediction Flow: Efficient Continuous Decoding for Masked Diffusion Language Models","authors":["Weitian Wang","Lianlei Shan","Shubham Rai","Cecilia De La Parra","Akash Kumar"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.29066","arxiv":"2606.29066","code":null,"overview":"The authors reinterpret mask prediction as clean-state prediction, which induces a continuous flow in embedding space. Tokens can then accumulate partial progress and remain revisable.","n":1,"x":568.8,"y":464.8,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"Lastly, commitment can also be combined with revision. $\\boldsymbol{x}$-Prediction Flow uses a learned policy to choose progress increments from predictive confidence and current progress, and commits the most confident position at each step."}],"related":[]},{"id":"yu2026dsl","short":"DSL-LLaDA","cat":"hybrid","title":"DSL-LLaDA: Scaling Continuous Denoising to 8B Masked Diffusion LMs","authors":["Longxuan Yu","Yunshu Wu","Yu Fu","Siheng Xiong","Rob Brekelmans","Hui Liu","Yue Dong","Greg Ver Steeg"],"venue":"Findings of EMNLP","year":2026,"url":"https://arxiv.org/abs/2606.01024","arxiv":"2606.01024","code":null,"overview":"DSL-LLaDA lightly adapts a pretrained masked model to continuous denoising by replacing binary masking with per-token Gaussian corruption, which avoids training a continuous model from scratch.","n":1,"x":545.3,"y":412.2,"r":5.75,"mentions":[{"part":"6 Scaling Continuous Language Models","secTitle":"6.2.2 Adapting Pretrained Models","text":"DSL-LLaDA instead starts from the masked diffusion model LLaDA and replaces its mask inputs with continuous per-token Gaussian noise through continued pretraining."}],"related":[]},{"id":"bansal2026token","short":"TTCD","cat":"hybrid","title":"Token Time Continuous Diffusion for Language Modeling","authors":["Parikshit Bansal","Sujay Sanghavi"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2607.14106","arxiv":"2607.14106","code":null,"overview":"TTCD maps Gaussian noise deterministically to tokens and gives each token its own time, so more certain tokens can move from noise to text faster than others.","n":4,"x":569.5,"y":408.9,"r":7.0,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"TTCD chooses an ordering from the initial denoising prediction, whereas the flows underlying Asynchronous FLM (aFLM) can adjust tokenwise progress throughout generation."},{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"TTCD uses tokenwise time and fixes an ordering from the entropy of its initial predictions."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"TTCD learns shortcut models conditioned on starting and ending tokenwise times."},{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"Sudoku is the most common of these benchmarks for continuous language models, usually evaluated at four difficulty levels."}],"related":["suleymanzade2026thinking","deschenaux2026simplex","deschenaux2026language"]},{"id":"wu2023ar","short":"AR-Diffusion","cat":"hybrid","title":"AR-diffusion: Auto-regressive diffusion model for text generation","authors":["Tong Wu","Zhihao Fan","Xiao Liu","Hai-Tao Zheng","Yeyun Gong","Yelong Shen","Jian Jiao","Juntao Li","Zhongyu Wei","Jian Guo","Nan Duan","Weizhu Chen"],"venue":"NeurIPS","year":2023,"url":"https://arxiv.org/abs/2305.09515","arxiv":"2305.09515","code":"https://github.com/microsoft/ProphetNet","overview":"AR-Diffusion gives tokens on the left fewer denoising steps than tokens on the right, so that later tokens depend on earlier ones, as in natural language.","n":3,"x":594.0,"y":417.6,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"AR-Diffusion advances earlier positions sooner so that they inform later predictions."},{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Giving each position its own time allows some tokens to become informative while others are uncertain."},{"part":"5 Few-Step Generative Modeling","secTitle":"5.5.2 Commitment and Ordering in Flow Maps","text":"In flows, this can be expressed by giving each position its own time (Section 3.6)."}],"related":[]},{"id":"bhatt2026generating","short":"Random CSPs","cat":"hybrid","title":"Generating from Discrete Distributions Using Diffusions: Insights from Random Constraint Satisfaction Problems","authors":["Alankrita Bhatt","Mukur Gupta","Germain Kolossov","Andrea Montanari"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2603.20589","arxiv":"2603.20589","code":null,"overview":"The authors use random constraint satisfaction problems as a benchmark for discrete generation and show that theory predicts observed behavior. Continuous diffusions outperform masked diffusions in their study.","n":1,"x":635.3,"y":382.1,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"In this setting, Bhatt et al. showed that continuous diffusion outperforms masked diffusion."}],"related":[]},{"id":"jutras2026sticky","short":"Sticky Jumps","cat":"hybrid","title":"Sticky Jump Diffusions: A Unifying Framework for Discrete, Continuous, and Hybrid Diffusion","authors":["Pascal Jutras-Dubé","Patrick Pynadath","Jeremy Lu","Yuan Gao","Ruqi Zhang"],"venue":"NeurIPS","year":2026,"url":"https://arxiv.org/abs/2607.10951","arxiv":"2607.10951","code":"https://github.com/PascalJD/sticky-jump-diffusions","overview":"Sticky Jump Diffusions are continuous-time processes anchored at token embeddings. They recover masked, continuous, and hybrid diffusion as limits and train from one denoising classifier.","n":1,"x":673.0,"y":367.5,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Sticky Jump Diffusions incorporate this commitment through jumps from continuous states to token embeddings."}],"related":[]},{"id":"schiff2026clock","short":"Clock Diffusion","cat":"hybrid","title":"Clock Diffusion: Efficient Semi-Autoregressive Continuous Diffusion Language Models","authors":["Yair Schiff","Omer Belhasin","Roy Uziel","Matan Rusanovsky","Ran Zilberstein","Marianne Arriola","Gilad Turok","Guanghan Wang","Volodymyr Kuleshov","Michael Elad"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.00894","arxiv":"2610.00894","code":null,"overview":"Clock Diffusion uses position-dependent noise schedules to define semi-autoregressive continuous models, which adds variable-length generation and support for a key-value cache.","n":3,"x":590.4,"y":454.1,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"Clock Diffusion and Lafa combine position-dependent progress with conditioning on a completed prefix."},{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"Clock Diffusion's confidence-based sampler commits the longest contiguous prefix of the active window whose positions either pass a confidence threshold or complete their local denoising schedules."},{"part":"4 Inference Strategies","secTitle":"4.6 Inference Efficiency","text":"Clock Diffusion combines this computation with the next denoising pass, processing the newly committed tokens alongside the active noisy window."}],"related":["chavan2026large"]},{"id":"ren2026hierarchical","short":"HC-DLM","cat":"hybrid","title":"Hierarchical Continuous Diffusion Language Models","authors":["Hui Ren","Zihan Li","Chang Liu","Huidong Liu","Alexander Schwing"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.02193","arxiv":"2610.02193","code":"https://github.com/rhfeiyang/HC-DLM","overview":"HC-DLM couples discrete token generation with a continuous latent trajectory, so that the tokens decoded together stay tied to a shared state.","n":1,"x":566.9,"y":384.7,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"HC-DLM reads out token predictions from the latent state at each step, re-noises them, and uses them to condition the next latent update."}],"related":[]},{"id":"gong2023diffuseqv2","short":"DiffuSeq-v2","cat":"hybrid","title":"DiffuSeq-v2: Bridging Discrete and Continuous Text Spaces for Accelerated Seq2Seq Diffusion Models","authors":["Shansan Gong","Mukai Li","Jiangtao Feng","Zhiyong Wu","Lingpeng Kong"],"venue":"Findings of EMNLP","year":2023,"url":"https://arxiv.org/abs/2310.05793","arxiv":"2310.05793","code":"https://github.com/Shark-NLP/DiffuSeq","overview":"DiffuSeq-v2 adds a soft absorbing state that helps the model learn discrete mutations from the underlying Gaussian space, which speeds up sequence-to-sequence training and sampling.","n":1,"x":613.4,"y":388.7,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.1 Sampling and Time Allocation","text":"DiffuSeq-v2 applied DPM-Solver++ to text diffusion early on."}],"related":[]},{"id":"li2025unifying","short":"NeoDiff","cat":"hybrid","title":"Unifying Continuous and Discrete Text Diffusion with Non-simultaneous Diffusion Processes","authors":["Bocheng Li","Zhujin Gao","Linli Xu"],"venue":"ACL","year":2025,"url":"https://arxiv.org/abs/2505.22165","arxiv":"2505.22165","code":null,"overview":"NeoDiff unifies discrete and continuous text diffusion. Tokens diffuse at different rates, which gives fine-grained noise with per-token progress.","n":1,"x":658.8,"y":386.0,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.6 Commitment and Ordering","text":"NeoDiff corrupts tokens with a Poisson process and estimates their progress with a learned predictor."}],"related":[]},{"id":"uziel2026crocodil","short":"CRoCoDiL","cat":"hybrid","title":"CRoCoDiL: Continuous and Robust Conditioned Diffusion for Language","authors":["Roy Uziel","Omer Belhasin","Itay Levy","Akhiad Bercovich","Ran El-Yaniv","Ran Zilberstein","Michael Elad"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2603.20210","arxiv":"2603.20210","code":null,"overview":"CRoCoDiL shifts masked diffusion into a continuous sentence-level semantic space. An encoder and demasker train jointly, which addresses incoherence between tokens.","n":1,"x":454.7,"y":335.6,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.4 Compressed Latent Representations","text":"DiLaDiff conditions a masked diffusion decoder on generated continuous latents, using the shared latent information to coordinate its token predictions, and CRoCoDiL obtains such a decoder by fine-tuning a pretrained masked diffusion model jointly with the encoder."}],"related":[]},{"id":"dilip2026guide","short":"Probe Guidance","cat":"guide","title":"How to Guide Your Language Flow","authors":["Rohit Dilip","Tianrong Chen","Yuyang Wang","David Van Valen","Josh Susskind","Miguel Angel Bautista"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.19356","arxiv":"2609.19356","code":null,"overview":"Probe guidance builds a guidance signal from the frozen internal states of a diffusion model. It works like autoguidance but needs no additional forward pass at inference time.","n":1,"x":429.7,"y":686.0,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"Probe Guidance reduces this overhead by training a small prediction head on the main model's intermediate features, so the reference reuses the same backbone evaluation."}],"related":[]},{"id":"huang2026guide","short":"FMRG","cat":"guide","title":"How to guide your flow: Few-step alignment via flow map reward guidance","authors":["Jerry Y Huang","Justin Lin","Sheel Shah","Kartik Nair","Nicholas M Boffi"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2604.27147","arxiv":"2604.27147","code":"https://github.com/jrrhuang/fmrg","overview":"FMRG reformulates guidance as deterministic optimal control, and the flow map arises naturally in the solution. This gives few-step reward guidance without expensive many-step schemes.","n":1,"x":449.2,"y":674.9,"r":5.75,"mentions":[{"part":"5 Few-Step Generative Modeling","secTitle":"5.4.2 Guiding the Flow Map","text":"Flow Map Reward Guidance (FMRG), applied to language by FMLM, alternates a step of the flow map with a step along the gradient of the reward evaluated on the lookahead, … where $\\lambda$ controls the strength of guidance."}],"related":[]},{"id":"shen2026flashmap","short":"FlashMap","cat":"guide","title":"FlashMap: Flow Map Speculative Decoding","authors":["Jeff Shen","Zhejian Zhou","Ryan Lee","Jonathan May","Shirley Ho"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.24365","arxiv":"2610.24365","code":"https://github.com/al-jshen/flashmap","overview":"FlashMap is a speculative decoding drafter. It conditions a flow map language model on the target model's hidden states to draft a whole block in one pass while capturing dependencies between tokens.","n":2,"x":544.8,"y":633.9,"r":6.27,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.6 Inference Efficiency","text":"FlashMap uses a flow-based drafter conditioned on the target model's hidden states to propose tokens jointly."},{"part":"8 Challenges and Future Directions","secTitle":"8.2 Scaling Pretraining and Few-Step Distillation","text":"Adaptation provides a pragmatic route to strong models by reusing linguistic knowledge and hardware-efficient implementations, and enables practical uses, especially speculative decoding."}],"related":["chavan2026large"]},{"id":"zhang2026low","short":"ACE","cat":"guide","title":"A Dominant Self-Conditioning Direction Drives Repetition in Unconditional Continuous Diffusion Language Models","authors":["Shuai Zhang","Zijie Chen","Huachuan Qiu","Hongliang He","Lun Du","Zhenzhong Lan"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2607.00588","arxiv":"2607.00588","code":"https://github.com/ZhangShuai1230/ACE-DLM","overview":"The authors link repetition in ELF to a self-conditioning feedback loop. Their training-free method, ACE, estimates a repetition direction and subtracts it from the feedback during denoising.","n":2,"x":573.1,"y":553.7,"r":6.27,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.3 Self-Conditioning and Iterative Refinement","text":"ACE estimates a repetition direction by contrasting feedback from high- and low-repetition calibration trajectories."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Repeated feedback can also increase confidence and reinforce repetitive text, motivating the inference adjustments discussed in Section 4.3."}],"related":["shabalin2025tencdm"]},{"id":"inference_ye2024dinoiser","short":"DINOISER","cat":"guide","title":"DINOISER: Diffused Conditional Sequence Learning by Manipulating Noises","authors":["Jiasheng Ye","Zaixiang Zheng","Yu Bao","Lihua Qian","Mingxuan Wang"],"venue":"arXiv","year":2024,"url":"https://arxiv.org/abs/2302.10025","arxiv":"2302.10025","code":"https://github.com/yegcjs/DINOISER","overview":"DINOISER shows that noise scale decides how much discreteness remains in embeddings. It adapts the noise scales sampled in training and amplifies them at inference so that the model uses source conditions better.","n":1,"x":610.8,"y":659.4,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"Difformer and DINOISER instead predict target lengths and generate candidates across several lengths and noise initializations."}],"related":["gao2022empowering"]},{"id":"kim2026continuous","short":"Diffinity","cat":"guide","title":"Continuous Diffusion Models Can Obey Formal Syntax","authors":["Jinwoo Kim","Taylor Berg-Kirkpatrick","Loris D'Antoni"],"venue":"ICML","year":2026,"url":"https://arxiv.org/abs/2602.12468","arxiv":"2602.12468","code":"https://github.com/large-loris-models/Diffinity","overview":"Diffinity steers continuous models to satisfy regular expressions without training. An analytic score estimates the probability that a latent state decodes to a valid string, and its gradient guides sampling.","n":1,"x":579.0,"y":620.2,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.2 Guidance and Control","text":"Diffinity extends such control to constraints specified as regular expressions."}],"related":[]},{"id":"rekesh2026inverseconfidence","short":"INCO","cat":"guide","title":"Inverse-Confidence Sampling for Continuous Diffusion Language Models","authors":["Andrei Rekesh","Jarrid Rector-Brooks","Cheng-Hao Liu"],"venue":"ICML Workshop","year":2026,"url":"https://scholar.google.com/scholar?q=Inverse-Confidence+Sampling+for+Continuous+Diffusion+Language+Models","arxiv":null,"code":null,"overview":"INCO assigns larger denoising steps to less confident positions, which improves the sample quality of LangFlow without retraining.","n":1,"x":625.1,"y":686.7,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"Inverse-Confidence Sampling (INCO) assigns larger denoising steps to less confident positions, and finds that this improves LangFlow's sample quality without retraining."}],"related":[]},{"id":"li2026improving","short":"Untied Self-Cond.","cat":"guide","title":"Improving Few-Step Language Flows with Untied Self-Conditioning","authors":["Bocheng Li","Linli Xu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2608.22244","arxiv":"2608.22244","code":null,"overview":"The authors trace few-step degradation to a mismatch in self-conditioning between training and sampling, and they derive a corrected form that unties the two.","n":1,"x":552.3,"y":572.7,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.3 Self-Conditioning and Iterative Refinement","text":"In self-conditioned flows, Untied Self-Conditioning observes that the previous prediction has already influenced the current state through the solver before it is supplied again as explicit feedback."}],"related":[]},{"id":"vaina2024diffusion","short":"Stopping Criteria","cat":"guide","title":"Diffusion Language Models Generation Can Be Halted Early","authors":["Sofia Maria Lo Cicero Vaina","Nikita Balagansky","Daniil Gavrilov"],"venue":"arXiv","year":2023,"url":"https://arxiv.org/abs/2305.10818","arxiv":"2305.10818","code":null,"overview":"The authors estimate how complete a text generation is and adaptively halt it. This allows more generation steps within a fixed time budget.","n":1,"x":597.0,"y":681.5,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"Vaina et al. study stopping criteria based on low predictive entropy, small KL divergence between successive predictions, or few token changes over several consecutive steps."}],"related":[]},{"id":"davis2026design","short":"DoubleCat / SemiCat","cat":"guide","title":"On the Design Space of Continuous Diffusion Language Models","authors":["Oscar Davis","Daan Roos","Alice Bizeul","Amitis Shidani","Victor Turrisi","Louis Béthune","Pierre Ablin","Marco Cuturi"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.13834","arxiv":"2610.13834","code":null,"overview":"DoubleCat and SemiCat come from a study of self-conditioning and embedding geometry. The authors show that self-conditioning corrects a mismatch between training and inference, which suggests cheaper designs.","n":2,"x":537.6,"y":592.3,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.7 What Makes a Good Representation?","text":"DoubleCat and SemiCat further connect self-conditioning to representation geometry, finding that it helps identify tokens in noise-dominated states and reduces the mismatch between training near clean token embeddings and generation through uncertain intermediate predictions."},{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"DoubleCat and SemiCat show that feedback makes token information easier to identify under strong noise and helps bridge the gap between training near clean token representations and generating through uncertain intermediate predictions."}],"related":[]},{"id":"shabalin2026why","short":"Why Gaussian Fails","cat":"guide","title":"Why Gaussian Diffusion Models Fail on Discrete Data and How to Prevent It?","authors":["Alexander Shabalin","Simon Elistratov","Viacheslav Meshchaninov","Ildus Sadrtdinov","Dmitry Vetrov"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2604.02028","arxiv":"2604.02028","code":null,"overview":"The authors identify a critical sampling interval in which noisy discrete data becomes multimodal, so DDPM can enter low-density regions. They explain why self-conditioning and q-sampling help.","n":1,"x":590.2,"y":599.5,"r":5.75,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"Related work also finds that self-conditioning stabilizes predictions in regions poorly covered during training."}],"related":[]},{"id":"guo2026rangeswa","short":"RangeSWA","cat":"guide","title":"RangeSWA: Training-Free Length Extrapolation for Continuous Diffusion Language Models","authors":["Guangfu Guo","Xiaoqian Lu","Linsey Pang","Weiran Yao","Haolin Chen","Long Cheng","Kunpeng Liu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.42084","arxiv":"2610.42084","code":null,"overview":"RangeSWA extends generation past the training length without training. It combines sliding-window attention, summaries of distant blocks, and dynamic content retrieval.","n":1,"x":589.9,"y":639.6,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.5 Decoding and Termination","text":"RangeSWA lets a trained model generate beyond its training length by combining sliding-window attention with summaries of distant blocks."}],"related":[]},{"id":"yang2026graft","short":"GRAFT","cat":"guide","title":"GRAFT: Restoring the Missing Sampling Interface in Continuous Diffusion Language Models","authors":["Haoning Yang","Lili Pan"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.29136","arxiv":"2610.29136","code":null,"overview":"GRAFT identifies a hidden cost of never discretizing during sampling, namely a collapse of the lexical long tail, and it restores a sampling interface to continuous models.","n":1,"x":637.2,"y":708.6,"r":5.75,"mentions":[{"part":"4 Inference Strategies","secTitle":"4.4 Commitment and Ordering","text":"GRAFT instead commits rare candidates early and regenerates the rest, recovering rare words that averaging over candidates suppresses."}],"related":[]},{"id":"han2026backpropagating","short":"Verifier Backprop","cat":"guide","title":"Backpropagating Verifier Rewards Through Continuous Flow Language Models","authors":["Xu Han","Jiajing Hu","Li-Ping Liu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.19080","arxiv":"2610.19080","code":null,"overview":"The authors propose a post-training framework for continuous flow language models that backpropagates verifier rewards through the denoising steps to obtain pathwise gradients.","n":1,"x":510.6,"y":634.1,"r":5.75,"mentions":[{"part":"8 Challenges and Future Directions","secTitle":"8.3 Post-training","text":"Han et al. apply this idea to a flow language model, using a critic on intermediate token embeddings."}],"related":[]},{"id":"suleymanzade2026thinking","short":"Looped Flows","cat":"apps","title":"Thinking with Looped Flows","authors":["Ayhan Suleymanzade","Chanhyuk Lee","Floor Eijkelboom","Nicholas M Boffi","\\.Ismail \\.Ilkan Ceylan","Jinwoo Kim"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.11801","arxiv":"2609.11801","code":"https://github.com/MisakiTaro0414/looped-flows","overview":"Looped Flows train recurrent models with local denoising objectives at decreasing noise levels, which lets early updates support later ones even when gradients cover only a few updates.","n":3,"x":252.2,"y":647.0,"r":6.67,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"FRM uses predictions from its own inference trajectories as conditioning, while Looped Flows feeds back hidden states, trained across progressively lower corruption levels with shared noise."},{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"Looped Flows instead train recurrent updates with local denoising objectives and shared noise, so that hidden states carry the computation forward, even though gradients cover only a few iterations."},{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"Sudoku is the most common of these benchmarks for continuous language models, usually evaluated at four difficulty levels."}],"related":["deschenaux2026simplex","deschenaux2026language","bansal2026token"]},{"id":"helbling2026flow","short":"FRM","cat":"apps","title":"Flow Reasoning Models: Turning Flows Into Efficient Recurrent Reasoners","authors":["Alec Helbling","Andrey Bryutkin","Mauro Martino","Duen Horng Chau","Nima Dehmamy","Hendrik Strobelt"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.29150","arxiv":"2606.29150","code":"https://github.com/helblazer811/Flow-Reasoning-Models","overview":"FRMs self-condition a flow model on its own past outputs, which turns one-shot denoising into iterative refinement. They revise interdependent decisions in parallel to solve structured puzzles.","n":2,"x":225.1,"y":685.1,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.4 Self-Conditioning","text":"FRM uses predictions from its own inference trajectories as conditioning, while Looped Flows feeds back hidden states, trained across progressively lower corruption levels with shared noise."},{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"FRM applies self-conditioning (Section 3.4) recursively and trains the model on states that are produced by its own recursion."}],"related":[]},{"id":"batzolis2026multimodal","short":"Multimodal CoBit","cat":"apps","title":"Multimodal Co-Generation With Continuous Bitstream Diffusion","authors":["Georgios Batzolis","Georgios Kontos","Bruno Trentini","Pranam Chatterjee","Micha Livne","Mark Girolami","Luca Ambrogioni"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.14349","arxiv":"2610.14349","code":"https://github.com/GBATZOLIS/BitstreamDiffusion","overview":"Multimodal CoBit extends bitstream diffusion to joint and conditional generation across image-text, speech-text, and protein sequence-structure, using one training and sampling protocol.","n":1,"x":351.6,"y":615.4,"r":5.75,"mentions":[{"part":"8 Challenges and Future Directions","secTitle":"8.4 Multimodality","text":"Continuous representations allow text and other modalities to be generated through a shared process, unlike hybrids that pair AR text with diffusion over images."}],"related":["tao2026multimodal","li2026juice"]},{"id":"tao2026multimodal","short":"MF-1","cat":"apps","title":"Multimodal Flow: Unified Flow Modeling of Language and Vision in Embedding Spaces","authors":["Hongyuan Tao","Xinggang Wang","Lianghui Zhu","Yongkang Li","Yunchao Wei","Bin Feng","Shaoyu Chen","Qian Zhang","Chang Huang","Kai Yu"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2609.40362","arxiv":"2609.40362","code":"https://github.com/hustvl/Multimodal-Flow","overview":"MF-1 is a fully continuous generative model of language and vision. It organizes text blocks and images as ordered chunks in a shared chunk-causal flow backbone.","n":2,"x":355.6,"y":592.3,"r":6.27,"mentions":[{"part":"3 Continuous Language Models","secTitle":"3.1.3 Contextual Token Embeddings","text":"FMLM$^\\star$ and ELF-REG use causal hidden states from GPT-2 and Qwen, respectively, while MF-1 applies T5 independently within short token blocks."},{"part":"8 Challenges and Future Directions","secTitle":"8.4 Multimodality","text":"Continuous representations allow text and other modalities to be generated through a shared process, unlike hybrids that pair AR text with diffusion over images."}],"related":["li2026juice","batzolis2026multimodal"]},{"id":"franca2026hacking","short":"Hacking Gen PPL","cat":"apps","title":"Hacking Generative Perplexity: Why Unconditional Text Evaluation Needs New Metrics","authors":["Antonio Franca","Alexander Tong"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2606.08417","arxiv":"2606.08417","code":"https://github.com/antoniofrancaib/dlmbench","overview":"The authors explain why generative perplexity is unreliable. They construct training-free samplers that match or beat trained models on this metric at comparable entropy.","n":2,"x":208.8,"y":646.6,"r":6.27,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.1.2 Evaluation Metrics","text":"Franca and Tong go further and show that gPPL can be hacked while preserving the entropy close to that of the data."},{"part":"7 Applications and Evaluation","secTitle":"7.1.2 Evaluation Metrics","text":"These metrics expose the demonstrated failure modes of gPPL, although finite-sample estimates and chosen representations do not guarantee identification of the complete text distribution, and they reveal larger differences across NFE than gPPL does."}],"related":[]},{"id":"pynadath2026generative","short":"Generative Frontiers","cat":"apps","title":"Generative frontiers: Why evaluation matters for diffusion language models","authors":["Patrick Pynadath","Jiaxin Shi","Ruqi Zhang"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2604.02718","arxiv":"2604.02718","code":null,"overview":"This technical note discusses the limits of current evaluation for diffusion language models, including likelihood-based metrics, and proposes principled additions for reliable comparisons.","n":1,"x":228.1,"y":639.0,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.1.2 Evaluation Metrics","text":"Pynadath et al. make this tradeoff explicit by showing that generative perplexity and entropy are two competing components of the KL divergence to a reference distribution."}],"related":[]},{"id":"kornhardt2026sol","short":"SOL","cat":"apps","title":"SOL: Measuring Gaps between Text Distributions by Double Sliced Wasserstein Metrics","authors":["Gregor Kornhardt","Moritz Piening","Jannis Chemseddine","Gabriele Steidl"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.06513","arxiv":"2610.06513","code":"https://github.com/GregorKornhardt/SOL","overview":"SOL is a distance between text distributions. It compares the hidden states of a fixed transformer with a double sliced Wasserstein distance, and the authors prove it is a metric for injective transformers.","n":1,"x":245.8,"y":622.9,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.1.2 Evaluation Metrics","text":"SOL is a distributional metric that avoids the clustering step of MAUVE."}],"related":[]},{"id":"baek2026generative","short":"GRAM","cat":"apps","title":"Generative recursive reasoning","authors":["Junyeob Baek","Mingyu Jo","Minsu Kim","Mengye Ren","Yoshua Bengio","Sungjin Ahn"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2605.19376","arxiv":"2605.19376","code":null,"overview":"GRAM turns deterministic recursive latent reasoning into a probabilistic model with multiple trajectories, so one model can represent several solutions.","n":1,"x":206.6,"y":670.5,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.3.2 Multi-Solution Tasks","text":"To expose this failure, Baek et al. introduce multi-solution benchmarks and show that deterministic recursive reasoners lose accuracy as the number of valid solutions grows."}],"related":[]},{"id":"bai2026efficient","short":"Efficient FLM Reasoning","cat":"apps","title":"Efficient Reasoning with Flow Language Models","authors":["Hanru Bai","Faissal Izermine","Oscar Davis","T. Konstantin Rusch"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.09416","arxiv":"2610.09416","code":null,"overview":"The authors compare the reasoning efficiency of flow language models and discrete diffusion under matched denoising steps, to learn what the continuous sequence representation contributes.","n":1,"x":228.2,"y":660.3,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.3.1 Single-Solution Tasks","text":"Bai et al. also showed that under matched numbers of denoising steps, FLMs solve Sudoku and mazes more accurately than discrete diffusion, as their continuous states keep evidence for several candidates until the final decoding."}],"related":[]},{"id":"li2026juice","short":"JUICE","cat":"apps","title":"JUICE: Unified Multimodal Modeling in Pretrained Representation Spaces","authors":["Jiahan Li","Huangyuan Su","Shengbang Tong","Shusheng Yang","Ruihan Guo","Suozhi Huang","Hexu Zhao","Pratyusha Sharma","Sherry Yang","Jiatao Gu","Rob Fergus","Kyunghyun Cho"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2610.28801","arxiv":"2610.28801","code":"https://github.com/Ced3-han/JUICE-Code","overview":"JUICE generates images and text with one process, trained jointly from scratch in pretrained encoder spaces, instead of attaching a diffusion head to a language model.","n":1,"x":373.9,"y":607.0,"r":5.75,"mentions":[{"part":"8 Challenges and Future Directions","secTitle":"8.4 Multimodality","text":"Continuous representations allow text and other modalities to be generated through a shared process, unlike hybrids that pair AR text with diffusion over images."}],"related":["tao2026multimodal","batzolis2026multimodal"]},{"id":"caceresarroyo2026repurposing","short":"CHASE","cat":"apps","title":"Repurposing Protein Language Models for Latent Flow-Based Fitness Optimization","authors":["Amaru Caceres Arroyo","Lea Bogensperger","Ahmed Allam","Michael Krauthammer","Konrad Schindler","Dominik Narnhofer"],"venue":"arXiv","year":2026,"url":"https://arxiv.org/abs/2602.02425","arxiv":"2602.02425","code":null,"overview":"CHASE compresses protein language model embeddings into a compact latent space and trains conditional flow matching with classifier-free guidance to generate high-fitness variants.","n":1,"x":220.0,"y":569.4,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.2 Conditional Generation and Reward Guidance","text":"Classifier-free guidance also applies in latent spaces, as CHASE guides a flow over compressed protein language model embeddings toward high-fitness variants."}],"related":[]},{"id":"kong2025protflow","short":"ProtFlow","cat":"apps","title":"ProtFlow: Fast Protein Sequence Design via Flow Matching on Compressed Protein Language Model Embeddings","authors":["Zitai Kong","Yiheng Zhu","Yinlong Xu","Hanjing Zhou","Mingzhe Yin","Jialu Wu","Hongxia Xu","Chang-Yu Hsieh","Tingjun Hou","Jian Wu"],"venue":"arXiv","year":2025,"url":"https://arxiv.org/abs/2504.10983","arxiv":"2504.10983","code":null,"overview":"ProtFlow designs protein sequences quickly with flow matching on compressed protein language model embeddings.","n":1,"x":182.7,"y":530.7,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.1 Tasks and Datasets","text":"This has motivated new approaches to protein, peptide, DNA, and RNA sequence design and to small-molecule generation, including discrete diffusion, discrete flows, continuous flows over probabilities or over protein language model encodings, and flow maps."}],"related":["meshchaninov2024diffusion"]},{"id":"meshchaninov2024diffusion","short":"DiMA","cat":"apps","title":"Diffusion on Language Model Encodings for Protein Sequence Generation","authors":["Viacheslav Meshchaninov","Pavel Strashnov","Andrey Shevtsov","Fedor Nikolaev","Nikita Ivanisenko","Olga Kardymon","Dmitry Vetrov"],"venue":"ICML","year":2025,"url":"https://arxiv.org/abs/2403.03726","arxiv":"2403.03726","code":"https://github.com/MeshchaninovViacheslav/DiMA","overview":"DiMA is a latent diffusion framework on protein language model representations. The authors explore its design choices across encoders from 8M to 3B parameters.","n":1,"x":187.3,"y":552.6,"r":5.75,"mentions":[{"part":"7 Applications and Evaluation","secTitle":"7.4.1 Tasks and Datasets","text":"This has motivated new approaches to protein, peptide, DNA, and RNA sequence design and to small-molecule generation, including discrete diffusion, discrete flows, continuous flows over probabilities or over protein language model encodings, and flow maps."}],"related":["kong2025protflow"]}]};
